# --------------------------------------------------------------------------- S21
# Story S21 (TICK-739), kit TICK-749: docs/acceptance/S21/README.md. The folder
# needs the stack docs/acceptance/S21/tools/run-kit.sh prepares (400k tenant A
# incidents, `due_at` added, `description` masked) and the s21_* expectations
# it passes as --env-var (tools/expect.sql: a JSON scan of the records). The
# backfill outlives an access token, so its requests sign in again through
# lib/s21.js.
LIB_S21 = r"""// S21 acceptance (TICK-749): helpers for folder S21. Its requests wait for a
// backfill (minutes) and run p95 cells, longer than an access token lives
// (300 s), so every call signs in again when its token is close to expiry.
// Generated by docs/acceptance/guide/build/collection.py; edit it there.
const crypto = require('crypto');
const USERS = {
  admin_a_token: ['admin_a_username', 'admin_a_password'],
  alice_token: ['alice_username', 'alice_password'],
  bob_token: ['bob_username', 'bob_password'],
};

module.exports = (N, bru) => {
  const T = {
    // The token in v, signed in again when it expires within 90 s.
    async fresh(v) {
      const t = bru.getVar(v);
      if (t && N.jwt(t).exp * 1000 - Date.now() > 90000) return t;
      const [u, p] = USERS[v];
      const r = await N.token(N.v(u), N.v(p));
      if (r.status !== 200) throw new Error(`sign-in again for ${v}: HTTP ${r.status}`);
      bru.setVar(v, r.data.access_token);
      return r.data.access_token;
    },
    async call(v, method, path, data, headers = {}) {
      const h = { Authorization: 'Bearer ' + (await T.fresh(v)), ...headers };
      if (data !== undefined && !h['Content-Type']) h['Content-Type'] = 'application/json';
      const t0 = Date.now();
      const r = await N.send({ url: N.url('{{core_url}}' + path), method, headers: h, data });
      return { status: r.status, data: r.data, ms: Date.now() - t0 };
    },
    list(v, query) { return T.call(v, 'GET', '/api/v1/records/incident?' + query); },
    // The total contract of a list body (ADR-006-A2 A2-1): null when it holds,
    // else what is wrong. total_state is exact, capped or unknown; total is an
    // integer for exact (0 to 1,000) and capped (1,000) and null for unknown,
    // never 0; total_capped is true exactly when capped (absent otherwise).
    contract(b) {
      if (!b || typeof b !== 'object') return 'no body';
      const s = b.total_state;
      if (!['exact', 'capped', 'unknown'].includes(s)) return `total_state ${JSON.stringify(s)}`;
      if (!('total' in b)) return 'no total';
      if (s === 'unknown' && b.total !== null) return `unknown with total ${JSON.stringify(b.total)}`;
      if (s === 'exact' && !(Number.isInteger(b.total) && b.total >= 0 && b.total <= 1000)) return `exact with total ${JSON.stringify(b.total)}`;
      if (s === 'capped' && b.total !== 1000) return `capped with total ${JSON.stringify(b.total)}`;
      if ((b.total_capped === true) !== (s === 'capped')) return `total_capped ${JSON.stringify(b.total_capped)} with ${s}`;
      return null;
    },
    // Every record a filter lists, page by page (limit 200, next_cursor), with
    // each page's total_state and any page that breaks the total contract.
    async all(v, query) {
      const items = [], states = [], broken = [];
      let cursor = null, first = null, pages = 0;
      do {
        const r = await T.list(v, query + '&limit=200' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''));
        if (r.status !== 200) throw new Error(`list ${query} as ${v}: HTTP ${r.status} ${JSON.stringify(r.data)}`);
        if (!first) first = r.data;
        const bad = T.contract(r.data);
        if (bad) broken.push(`page ${pages + 1}: ${bad}`);
        states.push(r.data.total_state);
        items.push(...r.data.items);
        cursor = r.data.next_cursor;
        pages++;
      } while (cursor);
      return { items, ids: items.map(i => i.id), first, pages, states, broken };
    },
    // md5 of the ids sorted as strings and joined by ',' (as tools/expect.sql).
    md5: (ids) => crypto.createHash('md5').update([...ids].sort().join(',')).digest('hex'),
    create(v, key, data) {
      return T.call(v, 'POST', '/api/v1/records/incident', { data }, { 'Idempotency-Key': key });
    },
    patch(v, key, id, version, data) {
      return T.call(v, 'PATCH', '/api/v1/records/incident/' + id, { data },
        { 'Idempotency-Key': key, 'Content-Type': 'application/merge-patch+json', 'If-Match': `W/"${version}"` });
    },
    // One p95 cell: `clients` callers list with `query` for `seconds` (after
    // 2 s of warm-up that is not counted), each paced to rate/clients
    // requests a second so the tenant stays under its 50/s rate limit. Counts
    // the total_state of every 200 (unknown_share is its percentage of them)
    // and keeps up to 5 bodies' contract breaks.
    async cell(v, query, seconds, { clients = 8, rate = 40 } = {}) {
      const tok = await T.fresh(v);
      const url = N.url('{{core_url}}/api/v1/records/incident' + (query ? '?' + query : ''));
      const period = (clients * 1000) / rate;
      const ms = [], statuses = {}, states = {}, broken = [];
      const warm = Date.now() + 2000, end = warm + seconds * 1000;
      const started_at = new Date(warm).toISOString();
      const client = async () => {
        while (Date.now() < end) {
          const t0 = Date.now();
          const r = await N.send({ url, method: 'GET', headers: { Authorization: 'Bearer ' + tok } });
          const t1 = Date.now();
          if (t0 >= warm) {
            ms.push(t1 - t0);
            statuses[r.status] = (statuses[r.status] || 0) + 1;
            if (r.status === 200) {
              const s = r.data && r.data.total_state;
              states[s] = (states[s] || 0) + 1;
              const bad = T.contract(r.data);
              if (bad && broken.length < 5) broken.push(bad);
            }
          }
          const wait = period - (t1 - t0);
          if (wait > 0) await bru.sleep(wait);
        }
      };
      await Promise.all(Array.from({ length: clients }, client));
      ms.sort((a, b) => a - b);
      const q = (p) => ms.length ? ms[Math.max(0, Math.ceil(p * ms.length) - 1)] : null;
      const ok = statuses[200] || 0;
      const unknown_share = ok ? Math.round(((states.unknown || 0) / ok) * 1000) / 10 : null;
      return { started_at, n: ms.length, rps: Math.round((ms.length / seconds) * 10) / 10, p50: q(0.5), p95: q(0.95), max: ms[ms.length - 1], statuses,
               total_states: states, unknown_share, broken };
    },
  };
  return T;
};
"""

S21_T = LOAD_PRE + "\nconst T = require('./lib/s21')(N, bru);"
S21_TT = "const T = require('./lib/s21')(N, bru);"
# The values the kit writes (criterion 4) and the marked values of seed.sql
# (criterion 5).
S21_VC = "2026-12-30T12:00:17Z"
S21_VD = "2026-12-30T12:00:18Z"
S21_HIDDEN = "2026-12-31T23:59:59Z"
S21_CONTROL = "2026-12-31T23:57:59Z"
S21_NOWHERE = "2026-12-31T23:58:59Z"
S21_AC2 = "filter[priority][gte]=2&filter[due_at][lt]=2026-01-01T12:00:00Z"


def s21():
    inc = "{{core_url}}/api/v1/records/incident"
    et = "{{core_url}}/api/v1/entity-types/incident"

    def exact(n, who, tok, query, var, desc, check):
        return req(
            n, "GET", inc + "?" + query, auth=tok,
            pre=S21_T + f"""
const all = await T.all('{tok}', '{query}');
bru.setVar('s21_all_{var}', JSON.stringify({{ ids: all.ids, pages: all.pages, states: all.states, broken: all.broken, items: all.items.map(i => ({{ priority: i.data.priority, due_at: i.data.due_at }})) }}));""",
            desc=desc,
            tests=f"""N.status(200);
{S21_TT}
const all = JSON.parse(bru.getVar('s21_all_{var}'));
const want = Number(N.v('s21_{var}_n'));
test(`{who}: ${{all.ids.length}} records over ${{all.pages}} pages; the JSON scan has ${{want}}`, () => expect(all.ids.length).to.eql(want));
test('the same records as the JSON scan (md5 of the sorted ids)', () => expect(require('crypto').createHash('md5').update([...all.ids].sort().join(',')).digest('hex')).to.eql(N.v('s21_{var}_md5')));
test('no record listed twice', () => expect(new Set(all.ids).size).to.eql(all.ids.length));
const first = N.json();
test(`every page meets the total contract (A2-1): this page ${{first.total_state}}, the limit-200 pages ${{JSON.stringify(all.states)}}`, () => {{
  expect(T.contract(first)).to.eql(null);
  expect(all.broken).to.eql([]);
}});
test('total: exact up to 1,000, capped at 1,000 past it, or null when unknown', () => {{
  if (first.total_state === 'unknown') expect(first.total).to.eql(null);
  else {{ expect(first.total).to.eql(Math.min(want, 1000)); expect(first.total_state).to.eql(want > 1000 ? 'capped' : 'exact'); }}
}});
if (want < 50) test(`a short result (${{want}} < 50 matches): exact on the first page (A2-4)`, () => {{
  expect(first.total_state).to.eql('exact');
  expect(first.total).to.eql(want);
}});
test('every listed record matches the filter', () => expect(all.items.filter(d => !({check})).length).to.eql(0));
bru.setVar('s21_ids_{var}', JSON.stringify(all.ids));""")

    p1 = "d.priority === 1"
    ac2 = "d.priority >= 2 && Date.parse(d.due_at) < Date.parse('2026-01-01T12:00:00Z')"

    return {
        "dir": "S21", "name": "S21 filterable fields",
        "desc": "Story S21, TICK-739 (kit TICK-749, docs/acceptance/S21/README.md): an admin flags a top-level field of a ticket type `x-nava-filterable` (ADR-006), the platform indexes it, and a list filters on it. Needs the stack docs/acceptance/S21/tools/run-kit.sh prepares: tenant A's incident type with `due_at` (date-time) and `description` masked to the admins group, 400,000 tenant A incidents and 50 tenant B ones, and the s21_* expectations (a JSON scan of the records) passed as environment variables. Story users: `admin@tenant-a` publishes, `agent@tenant-a` is Alice (service-desk: she reads about 5% of the incidents), `agent@tenant-b` is Bob. AC3 (S21.5-S21.7): unflagged and masked fields are refused. S21.8 flags `priority` (number) and `due_at` (date-time). AC1 (S21.9, S21.11, S21.13, S21.14): 422 `field_not_ready` with a whole-percentage `index_progress` while indexing, then exactly the rows of a JSON scan. AC4 (S21.10, S21.12): records created and edited while indexing and after are found. AC2 (S21.15, S21.16, S21.19): the range filter returns the right rows, and the list p95 is within ADR-006 D13 as amended by ADR-006-A1. AC5 (S21.17, S21.18): tenant B never matches, and a value only in a record Alice cannot see answers as a value that exists nowhere. Runs once per prepared stack: S21.8 publishes the flags.",
        "items": [
            token("S21.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s21_run', N.v('s21_run_id') || Math.random().toString(16).slice(2, 10));\nconsole.log('S21 run', bru.getVar('s21_run'));"),
            token("S21.2 Sign in as agent@tenant-a (Alice, service-desk)", "alice_username", "alice_password", "alice_token"),
            token("S21.3 Sign in as agent@tenant-b (Bob)", "bob_username", "bob_password", "bob_token"),
            req("S21.4 The incident type has priority and due_at, neither flagged yet", "GET", et, auth="admin_a_token",
                desc="run-kit.sh (tools/kit.mjs setup) added `due_at` before the seed. Kept for S21.8's publish body: the current schema, fixed columns and states.",
                tests="""N.status(200);
const b = N.json();
test('priority is an integer, due_at a date-time string', () => {
  expect(b.schema.properties.priority.type).to.eql('integer');
  expect(b.schema.properties.due_at).to.include({ type: 'string', format: 'date-time' });
});
test('no property is flagged x-nava-filterable yet (fresh stack)', () =>
  expect(Object.values(b.schema.properties).filter(p => p['x-nava-filterable']).length).to.eql(0));
bru.setVar('s21_prev', String(b.version));
bru.setVar('s21_def', JSON.stringify({ schema: b.schema, fixed_columns: b.fixed_columns, states: b.states }));"""),
            problem_req("S21.5 AC3: Alice filters on the masked field description: 400 masked_field", "GET",
                        inc + "?filter[description]=S21%20internal%20note%201", "masked_field", 400, auth="alice_token",
                        desc="`description` is masked to tenant A's admins group (tools/kit.mjs setup). Alice is not in it: 400 `masked_field`, before anything is read, and no `total`.",
                        extra="""test('no items and no total', () => { expect(N.json()).to.not.have.property('items'); expect(N.json()).to.not.have.property('total'); });"""),
            problem_req("S21.6 AC3: the admin filters on description, not flagged: 400 field_not_filterable", "GET",
                        inc + "?filter[description]=S21%20internal%20note%201", "field_not_filterable", 400, auth="admin_a_token",
                        desc="The mask admits the admin, so the same filter reaches the field-index registry: `description` is not flagged, so 400 `field_not_filterable` with `errors[]` at the filter.",
                        extra="N.fieldError('/filter/description');"),
            problem_req("S21.7 AC3: the admin filters on due_at before it is flagged: 400 field_not_filterable", "GET",
                        inc + "?filter[due_at]=2026-03-01T00:00:00Z", "field_not_filterable", 400, auth="admin_a_token",
                        desc="`due_at` exists in the schema but is not flagged yet (S21.8 flags it): 400 `field_not_filterable`. A filter on an unflagged field is never a JSON scan of 400k records.",
                        extra="N.fieldError('/filter/due_at');"),
            req("S21.8 The admin flags priority and due_at x-nava-filterable: 201", "POST", et + "/versions", auth="admin_a_token",
                headers={"Idempotency-Key": "s21-{{s21_run}}-flag"}, body={"definition": "set by the pre-request script"},
                pre=LOAD_PRE + """
const d = JSON.parse(bru.getVar('s21_def'));
d.schema.properties.priority['x-nava-filterable'] = true;
d.schema.properties.due_at['x-nava-filterable'] = true;
req.setBody({ definition: d });""",
                desc="The current schema with `\"x-nava-filterable\": true` on `priority` (number side table) and `due_at` (timestamp side table). Adding the flag is Compatible (ADR-006 D8). The publish writes the two registry rows in state `backfilling` and the outbox rows that start the backfill.",
                tests="""N.status(201);
const b = N.json();
test('the next version, compatible, current', () => {
  expect(b.version).to.eql(Number(bru.getVar('s21_prev')) + 1);
  expect(b.compat).to.eql('compatible');
  expect(b.current).to.eql(true);
});
test('both properties carry the flag', () => {
  expect(b.schema.properties.priority['x-nava-filterable']).to.eql(true);
  expect(b.schema.properties.due_at['x-nava-filterable']).to.eql(true);
});
bru.setVar('s21_flagged_at', String(Date.now()));"""),
            req("S21.9 AC1: while indexing, filter[priority]=1: 422 field_not_ready with index_progress", "GET",
                inc + "?filter[priority]=1", auth="admin_a_token",
                pre=S21_T + """
const r = await T.list('admin_a_token', 'filter[due_at]=2026-03-01T00:00:00Z');
bru.setVar('s21_due_not_ready', JSON.stringify({ status: r.status, body: r.data }));""",
                desc="Right after S21.8 the 400k backfill has only started. Both fields answer 422 `field_not_ready`; `index_progress` is the whole percentage done (0 to 99), and it is the only thing the body says about the field (no items, no total).",
                tests="""N.problem('field_not_ready', 422);
const b = N.json();
test('index_progress is a whole number from 0 to 99', () => {
  expect(Number.isInteger(b.index_progress)).to.eql(true);
  expect(b.index_progress).to.be.within(0, 99);
});
test('no items and no total', () => { expect(b).to.not.have.property('items'); expect(b).to.not.have.property('total'); });
const d = JSON.parse(bru.getVar('s21_due_not_ready'));
test('due_at too: 422 field_not_ready with a whole index_progress', () => {
  expect(d.status).to.eql(422);
  expect(d.body.code).to.eql('field_not_ready');
  expect(Number.isInteger(d.body.index_progress)).to.eql(true);
});
console.log('S21.9 index_progress priority', b.index_progress, 'due_at', d.body.index_progress);"""),
            req("S21.10 AC4: records created and edited while indexing", "GET", inc + "?filter[due_at]=" + S21_VC, auth="admin_a_token",
                pre=S21_T + """
const run = bru.getVar('s21_run');
const VC = '""" + S21_VC + """', VD = '""" + S21_VD + """';
const before = await T.list('admin_a_token', 'filter[due_at]=' + VC);
const edit = N.v('s21_edit_ids').split(',');
const out = { before: before.status, creates: [], edits: [], moved: null };
for (let i = 1; i <= 3; i++) {
  const r = await T.create('admin_a_token', `s21-${run}-during-${i}`, { short_description: `S21 ${run} created while indexing ${i}`, priority: 4, due_at: VC });
  out.creates.push({ status: r.status, id: r.data && r.data.id });
}
for (const id of edit.slice(0, 3)) {
  const r = await T.patch('admin_a_token', `s21-${run}-edit-during-${id}`, id, 1, { due_at: VC });
  out.edits.push({ status: r.status, id, version: r.data && r.data.version });
}
// Created on VC, then moved to VD while indexing: VC must not list it.
const m = await T.create('admin_a_token', `s21-${run}-moved`, { short_description: `S21 ${run} moved while indexing`, priority: 4, due_at: VC });
const mp = await T.patch('admin_a_token', `s21-${run}-moved-patch`, m.data.id, m.data.version, { due_at: VD });
out.moved = { create: m.status, patch: mp.status, id: m.data.id };
const p = await T.list('admin_a_token', 'filter[priority]=1');
out.priority_after = { status: p.status, index_progress: p.data && p.data.index_progress };
bru.setVar('s21_during', JSON.stringify(out));""",
                desc="While both fields are backfilling: 3 creates with `due_at` " + S21_VC + ", 3 seeded records edited to it (ids from tools/expect.sql, priority 4, so criteria 1 and 2 do not move), and one record created on it and then moved to " + S21_VD + ". This request, after all of them, still answers 422: every write happened before the flip. S21.12 finds them.",
                tests="""N.problem('field_not_ready', 422);
const o = JSON.parse(bru.getVar('s21_during'));
test('due_at was not ready before the writes either', () => expect(o.before).to.eql(422));
test('3 creates, each 201', () => expect(o.creates.map(c => c.status)).to.eql([201, 201, 201]));
test('3 edits, each 200 at version 2', () => {
  expect(o.edits.map(e => e.status)).to.eql([200, 200, 200]);
  expect(o.edits.map(e => e.version)).to.eql([2, 2, 2]);
});
test('the moved record: created 201, moved 200', () => { expect(o.moved.create).to.eql(201); expect(o.moved.patch).to.eql(200); });
test('priority still indexing after the writes', () => expect(o.priority_after.status).to.eql(422));"""),
            req("S21.11 AC1: wait until both fields are ready", "GET", inc + "?filter[priority]=1&limit=1", auth="admin_a_token",
                pre=S21_T + """
const limit = Number(N.v('s21_ready_limit_seconds') || 3600) * 1000;
const t0 = Number(bru.getVar('s21_flagged_at'));
const samples = [];
for (;;) {
  const p = await T.list('admin_a_token', 'filter[priority]=1&limit=1');
  const d = await T.list('admin_a_token', 'filter[due_at]=""" + S21_NOWHERE + """');
  const s = { s: Math.round((Date.now() - t0) / 1000), priority: p.status === 200 ? 'ready' : (p.data && p.data.index_progress), priority_status: p.status,
              due_at: d.status === 200 ? 'ready' : (d.data && d.data.index_progress), due_at_status: d.status };
  samples.push(s);
  if ((p.status === 200 && d.status === 200) || Date.now() - t0 > limit || ![200, 422].includes(p.status) || ![200, 422].includes(d.status)) break;
  await bru.sleep(15000);
}
bru.setVar('s21_ready', JSON.stringify(samples));""",
                desc="Polls both fields every 15 s from S21.8's publish until each answers 200 (at most `s21_ready_limit_seconds`, default 3600). The samples are the `index_progress` sequence; run-kit.sh's evidence keeps them. This request is the first 200.",
                tests="""N.status(200);
const ss = JSON.parse(bru.getVar('s21_ready'));
const last = ss[ss.length - 1];
test(`both fields ready after ${last.s} s and ${ss.length} polls`, () => { expect(last.priority_status).to.eql(200); expect(last.due_at_status).to.eql(200); });
test('every answer while indexing was 422 with a whole index_progress from 0 to 99', () => ss.forEach(s => ['priority', 'due_at'].forEach(f => {
  if (s[f + '_status'] === 422) expect(Number.isInteger(s[f]) && s[f] >= 0 && s[f] <= 99, JSON.stringify(s)).to.eql(true);
  else expect(s[f + '_status']).to.eql(200);
})));
test('index_progress never goes back, and once ready a field stays ready', () => ['priority', 'due_at'].forEach(f => {
  let prev = -1;
  ss.forEach(s => { const v = s[f] === 'ready' ? 100 : s[f]; expect(v, f + ' at ' + s.s + ' s').to.be.at.least(prev); prev = v; });
}));
console.log('S21.11 progress', JSON.stringify(ss));"""),
            req("S21.12 AC4: every write before and after the flip is found", "GET", inc + "?filter[due_at]=" + S21_VC + "&limit=200", auth="admin_a_token",
                pre=S21_T + """
const run = bru.getVar('s21_run');
const VC = '""" + S21_VC + """';
const edit = N.v('s21_edit_ids').split(',');
const out = { creates: [], edits: [] };
for (let i = 1; i <= 2; i++) {
  const r = await T.create('admin_a_token', `s21-${run}-after-${i}`, { short_description: `S21 ${run} created after the flip ${i}`, priority: 4, due_at: VC });
  out.creates.push({ status: r.status, id: r.data && r.data.id });
}
for (const id of edit.slice(3, 5)) {
  const r = await T.patch('admin_a_token', `s21-${run}-edit-after-${id}`, id, 1, { due_at: VC });
  out.edits.push({ status: r.status, id });
}
const vd = await T.list('admin_a_token', 'filter[due_at]=""" + S21_VD + """');
out.vd = { status: vd.status, ids: vd.data.items.map(i => i.id), total: vd.data.total, total_state: vd.data.total_state };
bru.setVar('s21_after', JSON.stringify(out));""",
                desc="After both fields are ready: 2 more creates and 2 more edits onto " + S21_VC + ". The filter lists exactly the 10 records written on it (5 created, 5 edited, during and after indexing) and not the one moved off it; " + S21_VD + " lists exactly that one.",
                tests="""N.status(200);
const d = JSON.parse(bru.getVar('s21_during')), a = JSON.parse(bru.getVar('s21_after'));
test('after the flip: 2 creates 201, 2 edits 200', () => {
  expect(a.creates.map(c => c.status)).to.eql([201, 201]);
  expect(a.edits.map(e => e.status)).to.eql([200, 200]);
});
const want = [...d.creates, ...d.edits, ...a.creates, ...a.edits].map(x => x.id).sort();
const got = N.json().items.map(i => i.id).sort();
test('exactly the 10 records written on the value, none missed across the flip', () => expect(got).to.eql(want));
test('total 10, exact: a short first page (A2-4)', () => { expect(N.json().total).to.eql(10); expect(N.json().total_state).to.eql('exact'); expect(N.json()).to.not.have.property('total_capped'); });
test('the record moved off the value while indexing is not listed', () => expect(got).to.not.include(d.moved.id));
test('the value it moved to lists exactly it', () => { expect(a.vd.status).to.eql(200); expect(a.vd.ids).to.eql([d.moved.id]); expect(a.vd.total).to.eql(1); expect(a.vd.total_state).to.eql('exact'); });"""),
            exact("S21.13 AC1: filter[priority]=1 as the admin gives exactly the JSON scan's rows", "admin", "admin_a_token",
                  "filter[priority]=1", "p1_admin",
                  "Every page of `filter[priority]=1` (limit 200) as the admin, against `tools/expect.sql`'s JSON scan of tenant A (`data->>'priority' = '1'`, 1% of 400k): the same count and the same ids. Every page meets the total contract (ADR-006-A2 A2-1): `total_state` exact, capped or unknown; `total` exact up to 1,000, 1,000 when capped, null when unknown. A result shorter than the page answers exact (A2-4).", p1),
            exact("S21.14 AC1: filter[priority]=1 as Alice gives exactly the JSON scan's rows she may read", "Alice", "alice_token",
                  "filter[priority]=1", "p1_agent",
                  "The same filter as Alice, against the JSON scan restricted to what the default incident ACL lets her read (assigned to service-desk, or raised by her).", p1),
            exact("S21.15 AC2: priority >= 2 and due_at before a date, as the admin: the right rows", "admin", "admin_a_token",
                  S21_AC2, "ac2_admin",
                  "`" + S21_AC2 + "`: a number range and a timestamp range together (about 0.13% of the type), against the JSON scan.", ac2),
            exact("S21.16 AC2: the same range filter as Alice: the right rows", "Alice", "alice_token",
                  S21_AC2, "ac2_agent",
                  "The same two range filters as Alice, against the JSON scan of what she may read.", ac2),
            req("S21.17 AC5: a value only in a record Alice cannot see answers as a value that exists nowhere", "GET",
                inc + "?filter[due_at]=" + S21_HIDDEN, auth="alice_token",
                pre=S21_T + """
const none = await T.list('alice_token', 'filter[due_at]=""" + S21_NOWHERE + """');
const ctl = await T.list('alice_token', 'filter[due_at]=""" + S21_CONTROL + """');
const adm = await T.list('admin_a_token', 'filter[due_at]=""" + S21_HIDDEN + """');
bru.setVar('s21_ac5', JSON.stringify({ none: { status: none.status, body: none.data }, control: { status: ctl.status, total: ctl.data.total, total_state: ctl.data.total_state },
  admin: { status: adm.status, total: adm.data.total, total_state: adm.data.total_state } }));""",
                desc="seed.sql gives one tenant A record `due_at` " + S21_HIDDEN + " and no group: the admin finds it, Alice may not read it. Alice's answer for it is the same as for " + S21_NOWHERE + ", which no record has: 200, no items, total 0. The control " + S21_CONTROL + " (a service-desk record) shows her filter does find what she may read.",
                tests="""N.status(200);
const o = JSON.parse(bru.getVar('s21_ac5'));
test('the admin finds the hidden value: total 1', () => { expect(o.admin.status).to.eql(200); expect(o.admin.total).to.eql(Number(N.v('s21_hidden_admin_n'))); expect(o.admin.total).to.eql(1); expect(o.admin.total_state).to.eql('exact'); });
test('Alice: no items, total 0, exact (never unknown: A2-4)', () => { expect(N.json().items).to.eql([]); expect(N.json().total).to.eql(0); expect(N.json().total_state).to.eql('exact'); });
test('the same status and body as a value that exists nowhere', () => { expect(o.none.status).to.eql(200); expect(N.json()).to.eql(o.none.body); });
test('the control value she may read: total 1, exact', () => { expect(o.control.status).to.eql(200); expect(o.control.total).to.eql(1); expect(o.control.total_state).to.eql('exact'); });"""),
            req("S21.18 AC5: tenant B's priority-1 records never match tenant A's filter", "GET", inc + "?filter[priority]=1&limit=200", auth="bob_token",
                pre=S21_T + "\nawait T.fresh('bob_token');",
                desc="Tenant B has 50 incidents, all priority 1. Bob's own list finds them (since S22, TICK-752, tenant B's seed type flags `priority` too, so it reads B's own index; kit.mjs setup creates the 50 through the API), and none of them is among the admin's S21.13 rows: tenant A's count is the tenant A scan, not the all-tenant one.",
                tests="""N.status(200);
const b = N.json();
const mine = b.items.map(i => i.id);
test(`Bob lists tenant B's ${N.v('s21_b_p1_n')} priority-1 incidents`, () => { expect(b.total).to.eql(Number(N.v('s21_b_p1_n'))); expect(mine.length).to.eql(b.total); expect(b.total_state).to.eql('exact'); });
const a = new Set(JSON.parse(bru.getVar('s21_ids_p1_admin')));
test("none of them is in tenant A's priority-1 list", () => expect(mine.filter(id => a.has(id)).length).to.eql(0));
test("tenant A's list is the tenant A scan, short of the all-tenant scan by tenant B's records", () =>
  expect(a.size).to.eql(Number(N.v('s21_p1_all_tenants_n')) - Number(N.v('s21_b_p1_n'))));"""),
            req("S21.19 AC2: list p95 within ADR-006 D13 (as amended by ADR-006-A1)", "GET", inc + "?limit=1", auth="admin_a_token",
                pre=S21_T + """
const secs = Number(N.v('s21_p95_seconds') || 15);
const a = Number(N.v('s21_a_n'));
const share = (n) => Math.round((Number(N.v(n)) / a) * 10000) / 100 + '%';
// The sixth column: the total_state every 200 of the cell must have. Only
// the >= 40% ACL cell is pinned (ADR-006-A2 A2-8 (7)): more than a page
// matches, so never exact, and its count may run out of budget.
const cells = [
  ['admin', 'admin_a_token', 'filter[priority]=1', share('s21_p1_admin_n') + ' of the type, 0.5-2% band, no narrowing ACL', 350, null],
  ['admin', 'admin_a_token', 'filter[priority]=3', share('s21_p3_admin_n') + ' of the type, >= 40% band, no narrowing ACL', 150, null],
  ['admin', 'admin_a_token', '""" + S21_AC2 + """', share('s21_ac2_admin_n') + ' of the type, below 0.5%, no narrowing ACL', 150, null],
  ['Alice', 'alice_token', 'filter[priority]=1', share('s21_p1_admin_n') + ' of the type, 0.5-2% band, narrowing ACL', 350, null],
  ['Alice', 'alice_token', 'filter[priority]=3', share('s21_p3_admin_n') + ' of the type, >= 40% band, narrowing ACL', 350, ['capped', 'unknown']],
  ['Alice', 'alice_token', '""" + S21_AC2 + """', share('s21_ac2_admin_n') + ' of the type, below 0.5%, narrowing ACL', 150, null],
  ['admin', 'admin_a_token', '', 'no filter (control, reported only)', null, null],
  ['Alice', 'alice_token', '', 'no filter (control, reported only)', null, null],
];
const out = [];
for (const [who, v, q, band, limit, allowed] of cells) {
  const r = await T.cell(v, q, secs);
  out.push({ who, filter: q || '(none)', band, limit_ms: limit, allowed_states: allowed, ...r });
  console.log(`S21.19 ${who} ${q || '(none)'}: p50 ${r.p50} p95 ${r.p95} max ${r.max} ms, ${r.n} requests (${r.rps}/s), ${JSON.stringify(r.statuses)}, total_state ${JSON.stringify(r.total_states)}, unknown ${r.unknown_share}%`);
}
bru.setVar('s21_p95', JSON.stringify(out));""",
                desc="Each cell: 8 clients list with the kit's filter for `s21_p95_seconds` (default 15 s) after 2 s of warm-up, paced to 40 requests a second together so the tenant stays under its 50/s rate limit (a 429 fails the cell). Latency is the client's, through nava-core and PgBouncer, default page (50). Limits (ADR-006 D13 as amended by ADR-006-A1, `docs/budgets.md`): 350 ms for the 0.5-2% band with or without a narrowing ACL and for the >= 40% band with one (Alice); 150 ms for every other filter. No 2-40% filter is asserted (unmeasured until TICK-1009). The no-filter control is reported, not scored. Every 200 meets the total contract (ADR-006-A2 A2-1); the >= 40% ACL cell's `total_state` is capped or unknown on every response, and every cell reports its share of `unknown` (expected high on a fresh stack, A2-7).",
                tests="""N.status(200);
const cells = JSON.parse(bru.getVar('s21_p95'));
cells.forEach(c => {
  test(`${c.who} ${c.filter} (${c.band}): only 200s, ${c.n} requests, p50 ${c.p50} p95 ${c.p95} max ${c.max} ms, from ${c.started_at}`, () => { expect(Object.keys(c.statuses)).to.eql(['200']); expect(c.n).to.be.above(0); });
  if (c.limit_ms !== null) test(`${c.who} ${c.filter}: p95 ${c.p95} ms <= ${c.limit_ms} ms (p50 ${c.p50}, max ${c.max})`, () => expect(c.p95).to.be.at.most(c.limit_ms));
  test(`${c.who} ${c.filter}: every 200 meets the total contract; total_state ${JSON.stringify(c.total_states)}, unknown ${c.unknown_share}%`, () => expect(c.broken).to.eql([]));
  if (c.allowed_states) test(`${c.who} ${c.filter}: every total_state in ${JSON.stringify(c.allowed_states)} (unknown ${c.unknown_share}%)`, () =>
    expect(Object.keys(c.total_states).filter(s => !c.allowed_states.includes(s))).to.eql([]));
});"""),
        ],
    }


# --------------------------------------------------------------------------- S18
# Number-format admin API (TICK-672, P6-07, ADR-005 §3.2, §4.2): create a
# format, publish a version, list, read. The story kit (TICK-677) extends this
# folder; these requests assert every documented status of the four operations.
def s18_api():
    nf = "{{core_url}}/api/v1/number-formats"
    one = nf + "/{{s18_id}}"
    key = lambda k: {"Idempotency-Key": "tick672-{{s18_run}}-" + k}
    ok_doc = {"template": "{prefix}-{yyyy}{MM}-{seq:4}", "overflow": "grow"}
    no404 = """
test('HTTP 404 problem+json, code not_found, no instance', () => {
  expect(res.getStatus()).to.eql(404);
  expect(N.header('Content-Type') || '').to.include('application/problem+json');
  expect(N.json().code).to.eql('not_found');
  expect(N.json()).to.not.have.property('instance');
});
N.status(404);"""
    return {
        "dir": "S18-API", "name": "S18 number-format API",
        "desc": "TICK-672 (P6-07, ADR-005 §3.2, §4.2): the tenant-admin number-format routes. Needs the stack with M3 applied, so a non-default format is accepted. Each request asserts one documented status. Formats are keyed per run, so the folder can run again.",
        "items": [
            token("S18.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s18_run', Math.random().toString(16).slice(2, 10));\nbru.setVar('s18_fmt', 'nf_' + bru.getVar('s18_run'));"),
            token("S18.2 Sign in as Alice (not an admin)", "alice_username", "alice_password", "alice_token"),
            token("S18.3 Sign in as Bob (tenant B)", "bob_username", "bob_password", "bob_token"),
            req("S18.4 Create a format: 201, version 1", "POST", nf, auth="admin_a_token", headers=key("create"),
                body={"key": "{{s18_fmt}}", "document": ok_doc},
                desc="`{key, document}`. The document is validated and compiled; the reply has the stored document, the compiled form and its SHA-256.",
                tests="""
test('HTTP 201, ETag W/"1", version 1', () => {
  expect(res.getStatus()).to.eql(201);
  expect(N.header('ETag')).to.eql('W/"1"');
  expect(N.json().version).to.eql(1);
  expect(N.json().key).to.eql(bru.getVar('s18_fmt'));
  expect(N.json().compiled_sha256).to.match(/^[0-9a-f]{64}$/);
});
bru.setVar('s18_id', N.json().id);
N.status(201);"""),
            problem_req("S18.5 Create the same key again: 409", "POST", nf, "number_format_exists", 409, auth="admin_a_token", headers=key("dup"),
                        body={"key": "{{s18_fmt}}", "document": ok_doc}, desc="A key is unique per tenant."),
            problem_req("S18.6 A template that does not start with {prefix}: 422", "POST", nf, "number_format_prefix_required", 422,
                        auth="admin_a_token", headers=key("nopfx"),
                        body={"key": "{{s18_fmt}}_p", "document": {"template": "X{prefix}{seq:4}", "overflow": "grow"}},
                        desc="`errors[].pointer` is `/document/template`, the rule `position:0`.",
                        extra="test('names the position', () => expect(N.json().errors[0].rule).to.eql('position:0'));"),
            problem_req("S18.7 A template with no {seq:N}: 422", "POST", nf, "number_format_invalid", 422,
                        auth="admin_a_token", headers=key("noseq"),
                        body={"key": "{{s18_fmt}}_s", "document": {"template": "{prefix}-{yyyy}", "overflow": "grow"}}),
            problem_req("S18.8 Create without a token: 401", "POST", nf, "invalid_token", 401, headers=key("anon"),
                        body={"key": "{{s18_fmt}}_a", "document": ok_doc}),
            problem_req("S18.9 Alice (not an admin) creates: 403", "POST", nf, "forbidden", 403, auth="alice_token", headers=key("alice"),
                        body={"key": "{{s18_fmt}}_b", "document": ok_doc}, desc="The admin check runs first."),
            problem_req("S18.10 Create without an Idempotency-Key: 400", "POST", nf, "validation_failed", 400, auth="admin_a_token",
                        body={"key": "{{s18_fmt}}_c", "document": ok_doc}),
            req("S18.11 List the formats: 200", "GET", nf, auth="alice_token",
                desc="Any user of the tenant. Ordered by key.",
                tests="""
test('HTTP 200, the format of S18.4 is listed', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().items.map((i) => i.id)).to.include(bru.getVar('s18_id'));
});
N.status(200);"""),
            problem_req("S18.12 List with limit=0: 400", "GET", nf + "?limit=0", "validation_failed", 400, auth="alice_token", desc="`limit` is 1 to 200."),
            problem_req("S18.13 List without a token: 401", "GET", nf, "invalid_token", 401, desc="Every route authenticates first."),
            req("S18.14 Read the format: 200", "GET", one, auth="alice_token",
                tests="""
test('HTTP 200, current version 1', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().current_version).to.eql(1);
});
N.status(200);"""),
            problem_req("S18.15 Read with version=0: 400", "GET", one + "?version=0", "validation_failed", 400, auth="alice_token", desc="`version` is at least 1."),
            problem_req("S18.16 Read without a token: 401", "GET", one, "invalid_token", 401, desc="Every route authenticates first."),
            req("S18.17 Bob reads tenant A's format: 404", "GET", one, auth="bob_token",
                desc="The same 404 as an unknown id, byte for byte, with no `instance`.", tests=no404),
            problem_req("S18.18 Publish without If-Match: 428", "PUT", one, "if_match_required", 428, auth="admin_a_token", headers=key("p428"),
                        body={"document": ok_doc}),
            problem_req("S18.19 Publish on a stale If-Match: 412", "PUT", one, "version_conflict", 412, auth="admin_a_token",
                        headers={**key("p412"), "If-Match": 'W/"9"'}, body={"document": ok_doc},
                        desc="The current `ETag` is in the response header."),
            problem_req("S18.20 Publish an invalid document: 422", "PUT", one, "number_format_invalid", 422, auth="admin_a_token",
                        headers={**key("p422"), "If-Match": 'W/"1"'}, body={"document": {"template": "{prefix}", "overflow": "grow"}},
                        desc="A template with no `{seq:N}`."),
            req("S18.21 Publish version 2: 200", "PUT", one, auth="admin_a_token", headers={**key("p200"), "If-Match": 'W/"1"'},
                body={"document": {"template": "{prefix}-{yy}{MM}-{seq:5}", "overflow": "refuse"}},
                tests="""
test('HTTP 200, ETag W/"2", version 2 is current', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.header('ETag')).to.eql('W/"2"');
  expect(N.json().version).to.eql(2);
  expect(N.json().current_version).to.eql(2);
});
N.status(200);"""),
            problem_req("S18.22 Publish without a token: 401", "PUT", one, "invalid_token", 401, headers={**key("p401"), "If-Match": 'W/"2"'},
                        body={"document": ok_doc}),
            problem_req("S18.23 Alice publishes: 403", "PUT", one, "forbidden", 403, auth="alice_token", headers={**key("p403"), "If-Match": 'W/"2"'},
                        body={"document": ok_doc}, desc="The admin check runs first."),
            req("S18.24 Publish an unknown id: 404", "PUT", nf + "/00000000-0000-4000-8000-00000000ffff", auth="admin_a_token",
                headers={**key("p404"), "If-Match": 'W/"1"'}, body={"document": ok_doc}, tests=no404),
            problem_req("S18.25 Publish without an Idempotency-Key: 400", "PUT", one, "validation_failed", 400, auth="admin_a_token",
                        headers={"If-Match": 'W/"2"'}, body={"document": ok_doc}),
            # Re-publish linked types (TICK-673, P6-08, ADR-005 section 3.2, 3.7 C13).
            req("S18.26 Re-publish linked types: 200, no type is linked yet", "POST", one + "/republish-linked", auth="admin_a_token",
                headers=key("rl200"), body={"version": 2},
                desc="`{version}`: one independent publish per type pinned to an older version of the format, reported per type. No type is linked in this folder, so `results` is empty.",
                tests="""
test('HTTP 200, the report names the format and version', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().format_id).to.eql(bru.getVar('s18_id'));
  expect(N.json().version).to.eql(2);
  expect(N.json().results).to.be.an('array');
});
N.status(200);"""),
            problem_req("S18.27 Re-publish without a token: 401", "POST", one + "/republish-linked", "invalid_token", 401, headers=key("rl401"),
                        body={"version": 2}),
            problem_req("S18.28 Alice re-publishes: 403", "POST", one + "/republish-linked", "forbidden", 403, auth="alice_token",
                        headers=key("rl403"), body={"version": 2}, desc="The admin check runs first."),
            req("S18.29 Re-publish an unknown format: 404", "POST", nf + "/00000000-0000-4000-8000-00000000ffff/republish-linked",
                auth="admin_a_token", headers=key("rl404"), body={"version": 2}, tests=no404),
            problem_req("S18.30 Re-publish a version the format does not have: 422", "POST", one + "/republish-linked",
                        "number_format_not_found", 422, auth="admin_a_token", headers=key("rl422"), body={"version": 99}),
            problem_req("S18.31 Re-publish without an Idempotency-Key: 400", "POST", one + "/republish-linked", "validation_failed", 400,
                        auth="admin_a_token", body={"version": 2}),
        ],
    }


# --------------------------------------------------------------------------- S18 time zone
# Tenant time-zone route (TICK-672, P6-07, ADR-005 section 3.6). The story kit
# (TICK-677) extends this folder.
def s18_tz():
    tz = "{{core_url}}/api/v1/tenant/settings/time-zone"
    key = lambda k: {"Idempotency-Key": "tick672-tz-{{s18tz_run}}-" + k}
    return {
        "dir": "S18-TZ", "name": "S18 tenant time zone",
        "desc": "TICK-672 (P6-07, ADR-005 section 3.6): the tenant-admin route that reads and sets the numbering time zone. Each request asserts one documented status. The folder sets tenant A's zone and sets it back to `UTC`, so it can run again.",
        "items": [
            token("S18T.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s18tz_run', Math.random().toString(16).slice(2, 10));"),
            token("S18T.2 Sign in as Alice (not an admin)", "alice_username", "alice_password", "alice_token"),
            req("S18T.3 Set the zone: 200", "PUT", tz, auth="admin_a_token", headers=key("set"), body={"time_zone": "Europe/Berlin"},
                desc="An IANA name. A change affects the scope keys of future allocations only, and is audited as `tenant_setting`.",
                tests="""
test('HTTP 200, the zone is in force', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().time_zone).to.eql('Europe/Berlin');
});
N.status(200);"""),
            req("S18T.4 Read the zone: 200", "GET", tz, auth="admin_a_token",
                tests="""
test('HTTP 200, Europe/Berlin', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().time_zone).to.eql('Europe/Berlin');
});
N.status(200);"""),
            problem_req("S18T.5 An unknown zone: 422", "PUT", tz, "invalid_time_zone", 422, auth="admin_a_token", headers=key("bad"),
                        body={"time_zone": "Mars/Base"}, desc="`errors[].pointer` is `/time_zone`; nothing is written."),
            problem_req("S18T.6 Set without a token: 401", "PUT", tz, "invalid_token", 401, headers=key("anon"), body={"time_zone": "UTC"}),
            problem_req("S18T.7 Alice sets the zone: 403", "PUT", tz, "forbidden", 403, auth="alice_token", headers=key("alice"),
                        body={"time_zone": "UTC"}, desc="The admin check runs first."),
            problem_req("S18T.8 Set without an Idempotency-Key: 400", "PUT", tz, "validation_failed", 400, auth="admin_a_token",
                        body={"time_zone": "UTC"}),
            problem_req("S18T.9 Read without a token: 401", "GET", tz, "invalid_token", 401),
            problem_req("S18T.10 Alice reads the zone: 403", "GET", tz, "forbidden", 403, auth="alice_token"),
            req("S18T.11 Set the zone back to UTC: 200", "PUT", tz, auth="admin_a_token", headers=key("reset"), body={"time_zone": "UTC"},
                tests="""
test('HTTP 200, UTC again', () => {
  expect(res.getStatus()).to.eql(200);
  expect(N.json().time_zone).to.eql('UTC');
});
N.status(200);"""),
        ],
    }


# --------------------------------------------------------------------------- S18 story
# Story S18 (TICK-669, release R2 of ADR-005), kit TICK-677:
# docs/acceptance/S18/README.md. docs/acceptance/S18/tools/run-kit.sh brings
# up a fresh stack on the S17 build, creates the `visa` (VISA) and `permit`
# (PMT) types in tenant A with default numbers, upgrades the stack to the
# story build (M3 runs) and runs this folder once. The exact numbers hold only
# on that stack, so the folder does not run again on the same stack.
# The definition matches DEFINITION in docs/acceptance/S18/tools/kit.mjs.
S18N_DEF = {
    "schema": {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "additionalProperties": False,
        "required": ["short_description", "state"],
        "properties": {
            "short_description": {"type": "string", "minLength": 1, "maxLength": 160},
            "state": {"type": "string", "enum": ["new", "closed"], "default": "new"},
        },
    },
    "fixed_columns": {"state": "state"},
    "states": {"initial": "new", "states": ["new", "closed"], "transitions": [{"from": "new", "to": "closed"}]},
}

# The month in the tenant's time zone, as {yyyy}{MM} renders it.
S18N_YM = r"""const ym = (tz) => {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit' }).formatToParts(new Date()).map(x => [x.type, x.value]));
  return p.year + p.month;
};"""

# Builds a publish body from the type's current definition (GET), with
# number_format set to __FMT__ (a JS expression).
S18N_LINK_PRE = LOAD_PRE + r"""
const tok = bru.getVar('__TOKEN__');
const cur = await N.send({ url: N.url('{{core_url}}/api/v1/entity-types/__TYPE__'), method: 'GET', headers: { Authorization: 'Bearer ' + tok } });
if (cur.status !== 200) throw new Error('GET __TYPE__: HTTP ' + cur.status);
bru.setVar('s18n_cur___TYPE__', String(cur.data.version));
req.setBody({ definition: { schema: cur.data.schema, fixed_columns: cur.data.fixed_columns, states: cur.data.states }, number_format: __FMT__ });
"""

S18N_FORCE = LOAD_PRE + r"""
// S18_FORCE_FAIL=1 (run-kit.sh): a second client takes the first formatted
// Visa number before this create, so it gets ...0002 and the kit must fail.
if (N.v('s18_force_fail') === '1') {
  const r = await N.send({ url: N.url('{{core_url}}/api/v1/records/visa'), method: 'POST',
    headers: { Authorization: 'Bearer ' + bru.getVar('admin_a_token'), 'Content-Type': 'application/json', 'Idempotency-Key': 's18n-' + bru.getVar('s18n_run') + '-force' },
    data: { data: { short_description: 'S18 forced failure: one extra Visa create' } } });
  console.log('S18 FORCED FAILURE: an extra Visa create took', r.data && r.data.number);
}
"""

S18N_FILL = LOAD_PRE + r"""
const tok = bru.getVar('admin_a_token');
const out = [];
for (let i = 1; i <= 9; i++) {
  const r = await N.send({ url: N.url('{{core_url}}/api/v1/records/permit'), method: 'POST',
    headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json', 'Idempotency-Key': 's18n-' + bru.getVar('s18n_run') + '-fill-' + i },
    data: { data: { short_description: 'S18 fill ' + i } } });
  out.push({ status: r.status, number: r.data && r.data.number, id: r.data && r.data.id });
}
bru.setVar('s18n_fill', JSON.stringify(out));"""

S18N_PERMIT_DEF = LOAD_PRE + r"""
// The permit type's id: the entity_definition_id of PMT-1's create entry.
const r = await N.send({ url: N.url('{{core_url}}/api/v1/audit/entries?domain=record&subject_type=record&subject_id=' + bru.getVar('s18n_pmt1_id')),
  method: 'GET', headers: { Authorization: 'Bearer ' + bru.getVar('admin_a_token') } });
const e = ((r.data && r.data.items) || [])[0];
if (!e || !e.entity_definition_id) throw new Error('no audit entry for PMT-1: HTTP ' + r.status);
bru.setVar('s18n_permit_def', e.entity_definition_id);"""

S18N_EXHAUSTED = r"""N.status(200);
const xs = (N.json().items || []).filter(e => e.action === 'number_space_exhausted');
test('exactly one number_space_exhausted entry', () => expect(xs.length).to.eql(1));
const e = xs[0] || {};
test('domain record, subject the permit type', () => {
  expect(e.domain).to.eql('record');
  expect(e.subject_type).to.eql('entity_definition');
  expect(e.subject_id).to.eql(bru.getVar('s18n_permit_def'));
});
const ops = Array.isArray(e.diff) ? e.diff : [];
const ns = (ops.find(o => o.path === '/number_space') || {}).value || {};
test(`diff /number_space has epoch, scope_key, width, counter: ${JSON.stringify(ns)}`, () => {
  expect(ns).to.have.all.keys('epoch', 'scope_key', 'width', 'counter');
  expect(ns.width).to.eql(1);
  expect(ns.counter).to.eql(10);
  expect(ns.epoch).to.be.at.least(1);
});"""


def s18_story():
    nf = "{{core_url}}/api/v1/number-formats"
    et = "{{core_url}}/api/v1/entity-types"
    rec = "{{core_url}}/api/v1/records"
    audit = "{{core_url}}/api/v1/audit/entries"
    ghost = "00000000-0000-4000-8000-00000000f18f"
    key = lambda k: {"Idempotency-Key": "s18n-{{s18n_run}}-" + k}
    body = lambda text: {"data": {"short_description": "S18 {{s18n_run}} " + text}}
    visa_link = {"definition": S18N_DEF, "number_format": {"id": "{{s18n_visa_fmt}}", "version": 1}}
    added = json.loads(json.dumps(S18N_DEF))
    added["schema"]["properties"]["passport_no"] = {"type": "string", "maxLength": 20}

    def link_pre(tok, typ, fmt):
        return S18N_LINK_PRE.replace("__TOKEN__", tok).replace("__TYPE__", typ).replace("__FMT__", fmt)

    no404 = """
test('HTTP 404 problem+json, code not_found, no instance', () => {
  expect(res.getStatus()).to.eql(404);
  expect(N.header('Content-Type') || '').to.include('application/problem+json');
  expect(N.json().code).to.eql('not_found');
  expect(N.json()).to.not.have.property('instance');
});
N.status(404);"""

    def fmt(name, k, tmpl, overflow, var, desc):
        return req(name, "POST", nf, auth="admin_a_token", headers=key(k),
                   body={"key": "s18n_%s_{{s18n_run}}" % k, "document": {"template": tmpl, "overflow": overflow}}, desc=desc,
                   tests=f"""N.status(201);
test('version 1 of {tmpl} ({overflow})', () => {{
  expect(N.json().version).to.eql(1);
  expect(N.json().document.template).to.eql('{tmpl}');
}});
bru.setVar('{var}', N.json().id);""")

    def visa(name, k, who, seq, desc, force=False):
        pre = (S18N_FORCE + "\n" if force else LOAD_PRE + "\n") + S18N_YM + "\nbru.setVar('s18n_ym_before', ym(N.v('s18_tz')));"
        want = "%04d" % seq
        return req(name, "POST", rec + "/visa", auth=who, headers=key(k), body=body(k), desc=desc, pre=pre,
                   tests=S18N_YM + f"""
N.status(201);
const n = N.json().number;
const months = [bru.getVar('s18n_ym_before'), ym(N.v('s18_tz'))];
test(`number VISA-<yyyymm in ${{N.v('s18_tz')}}>{want}: ${{n}}`, () => expect(months.map(m => 'VISA-' + m + '{want}')).to.include(n));
bru.setVar('s18n_{k}_id', N.json().id);
bru.setVar('s18n_{k}_number', n);
console.log('S18 {k}:', n);""")

    def inc(name, k, who, number, desc):
        return req(name, "POST", rec + "/incident", auth=who, headers=key(k), body=body(k), desc=desc,
                   tests=f"N.status(201);\ntest('number {number}', () => expect(N.json().number).to.eql('{number}'));")

    def read(name, who, path, number_expr, desc):
        return req(name, "GET", rec + path, auth=who, desc=desc,
                   tests=f"N.status(200);\nconst want = {number_expr};\ntest(`number still ${{want}}`, () => expect(N.json().number).to.eql(want));")

    pos = lambda p: ("test('names position %d of /document/template', () => {\n"
                     "  expect(N.json().errors[0].pointer).to.eql('/document/template');\n"
                     "  expect(N.json().errors[0].rule).to.eql('position:%d');\n});") % (p, p)

    return {
        "dir": "S18", "name": "S18 number formats",
        "desc": "Story S18, TICK-669 (kit TICK-677, docs/acceptance/S18/README.md): release R2 of ADR-005. A tenant admin writes a number format, publishes it and links it to a ticket type. Needs the stack docs/acceptance/S18/tools/run-kit.sh prepares: a fresh stack on the S17 build where tenant A has the types `visa` (VISA0000001, VISA0000002) and `permit` and incidents INC0000001..2, tenant B incidents INC0000001..2, then upgraded to the story build (M3), with admin@tenant-b.test seeded. Users: admin@tenant-a, agent@tenant-a (Alice) and admin@tenant-b. AC1 S18N.5-S18N.15, AC2 S18N.16-S18N.17, AC3 S18N.18-S18N.21, AC4 S18N.22-S18N.26, AC5 S18N.27-S18N.31, E9 S18N.32-S18N.38. Runs once per prepared stack: the exact numbers do not hold on a second pass.",
        "items": [
            token("S18N.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s18n_run', Math.random().toString(16).slice(2, 10));\nconsole.log('S18 run', bru.getVar('s18n_run'));"),
            token("S18N.2 Sign in as agent@tenant-a (Alice)", "alice_username", "alice_password", "alice_token"),
            token("S18N.3 Sign in as admin@tenant-b", "admin_b_username", "admin_b_password", "admin_b_token"),
            req("S18N.4 admin@tenant-b is tenant B's admin", "GET", "{{core_url}}/api/v1/me", auth="admin_b_token",
                desc="run-kit.sh seeded admin@tenant-b.test into tenant B's admins group.",
                tests=f"N.me('{B}');\ntest('in /admins', () => expect(N.paths()).to.include('/admins'));"),
            req("S18N.5 AC1: admin@tenant-a sets the tenant's numbering time zone", "PUT", "{{core_url}}/api/v1/tenant/settings/time-zone",
                auth="admin_a_token", headers=key("tz"), body={"time_zone": "{{s18_tz}}"},
                desc="The month in the number is the month in this zone (`s18_tz`; run-kit.sh uses `Pacific/Kiritimati`, UTC+14).",
                tests="N.status(200);\ntest('the zone is in force', () => expect(N.json().time_zone).to.eql(N.v('s18_tz')));"),
            fmt("S18N.6 AC1: admin@tenant-a writes and publishes {prefix}-{yyyy}{MM}{seq:4}", "visa", "{prefix}-{yyyy}{MM}{seq:4}", "refuse", "s18n_visa_fmt",
                "A date-then-sequence format must use `refuse` (ADR-005-E2)."),
            problem_req("S18N.7 AC1: agent@tenant-a cannot write a format: 403", "POST", nf, "forbidden", 403, auth="alice_token", headers=key("alice-fmt"),
                        body={"key": "s18n_alice_{{s18n_run}}", "document": {"template": "{prefix}-{yyyy}{MM}{seq:4}", "overflow": "refuse"}},
                        desc="Formats are for tenant admins."),
            problem_req("S18N.8 AC1: agent@tenant-a cannot link it: 403", "POST", et + "/visa/versions", "forbidden", 403, auth="alice_token",
                        headers=key("alice-link"), body=visa_link),
            req("S18N.9 AC1: admin@tenant-a links the format to the Visa type", "POST", et + "/visa/versions", auth="admin_a_token",
                headers=key("link"), body=visa_link,
                desc="`number_format` `{id, version}` with the same definition. The format cannot render a default number (`VISA` then 7 digits), so the publish takes a new epoch.",
                tests="""N.status(201);
test('version 2 pins the format, version 1', () => {
  expect(N.json().version).to.eql(2);
  expect(N.json().number_format).to.eql({ id: bru.getVar('s18n_visa_fmt'), version: 1 });
});"""),
            visa("S18N.10 AC1: the next Visa ticket is VISA-<yyyymm>0001", "visa1", "admin_a_token", 1,
                 "admin@tenant-a creates a Visa ticket. The month is the month now in the tenant's time zone.", force=True),
            visa("S18N.11 AC1: the next one is VISA-<yyyymm>0002 (agent@tenant-a)", "visa2", "alice_token", 2,
                 "Alice, an agent of tenant A, creates the next one."),
            inc("S18N.12 AC1: other types keep their numbers: tenant A's next incident is INC0000003", "inc-a3", "admin_a_token", "INC0000003",
                "The incident type has no format: it carries on on the default numbering."),
            inc("S18N.13 AC1: tenant B's next incident is INC0000003", "inc-b3", "admin_b_token", "INC0000003",
                "Tenant B is untouched by tenant A's format."),
            read("S18N.14 AC1: VISA0000001, issued before the upgrade, keeps its number", "admin_a_token", "/visa/{{s18_visa1_id}}", "'VISA0000001'",
                 "The record kit.mjs created on the S17 build."),
            read("S18N.15 AC1: VISA0000002 keeps its number (agent@tenant-a reads it)", "alice_token", "/visa/{{s18_visa2_id}}", "'VISA0000002'", ""),
            problem_req("S18N.16 AC2: {yyyy}{MM}{seq:4} is refused: 422 number_format_prefix_required", "POST", nf, "number_format_prefix_required", 422,
                        auth="admin_a_token", headers=key("nopfx"),
                        body={"key": "s18n_nopfx_{{s18n_run}}", "document": {"template": "{yyyy}{MM}{seq:4}", "overflow": "refuse"}},
                        desc="The template does not start with `{prefix}`.", extra=pos(0)),
            problem_req("S18N.17 AC2: {prefix}X{seq:4} is refused: 422 number_format_prefix_required", "POST", nf, "number_format_prefix_required", 422,
                        auth="admin_a_token", headers=key("letter"),
                        body={"key": "s18n_letter_{{s18n_run}}", "document": {"template": "{prefix}X{seq:4}", "overflow": "refuse"}},
                        desc="The token after `{prefix}` produces a letter, at byte 8.", extra=pos(8)),
            fmt("S18N.18 AC3: admin@tenant-a writes {prefix}{yy}{seq:3}", "short", "{prefix}{yy}{seq:3}", "refuse", "s18n_short_fmt",
                "On its own the format is valid."),
            problem_req("S18N.19 AC3: linking it to the incident type, which has default numbers, is refused: 422 number_format_overlap", "POST",
                        et + "/incident/versions", "number_format_overlap", 422, auth="admin_a_token", headers=key("overlap"), body={},
                        pre=link_pre("admin_a_token", "incident", "{ id: bru.getVar('s18n_short_fmt'), version: 1 }"),
                        desc="The pre-request script sends the incident type's current definition with the format. `INC`, two year digits and three digits can render a number the default numbering (`INC` then 7 digits) can issue.",
                        extra="test('errors name the clashing template', () => expect(N.json().errors.map(e => e.rule).join(' ')).to.match(/overlap:/));"),
            req("S18N.20 AC3: the refused link wrote nothing", "GET", et + "/incident", auth="admin_a_token",
                tests="N.status(200);\ntest('same version, default numbering', () => {\n  expect(String(N.json().version)).to.eql(bru.getVar('s18n_cur_incident'));\n  expect(N.json().number_format == null).to.eql(true);\n});"),
            inc("S18N.21 AC3: the incident type still numbers by default: INC0000004", "inc-a4", "admin_a_token", "INC0000004", ""),
            req("S18N.22 AC4: admin@tenant-a publishes an unrelated change to the Visa type (adds a field)", "POST", et + "/visa/versions",
                auth="admin_a_token", headers=key("addfield"), body={"definition": added},
                desc="No `number_format` field: the publish keeps the pinned format.",
                tests="""N.status(201);
test('version 3, compatible, still pins the format version 1', () => {
  expect(N.json().version).to.eql(3);
  expect(N.json().compat).to.eql('compatible');
  expect(N.json().schema.properties).to.have.property('passport_no');
  expect(N.json().number_format).to.eql({ id: bru.getVar('s18n_visa_fmt'), version: 1 });
});"""),
            visa("S18N.23 AC4: numbering carries on: the next Visa ticket is VISA-<yyyymm>0003", "visa3", "admin_a_token", 3, ""),
            read("S18N.24 AC4: the first formatted ticket keeps its number", "admin_a_token", "/visa/{{s18n_visa1_id}}", "bru.getVar('s18n_visa1_number')", ""),
            read("S18N.25 AC4: VISA0000001 keeps its number", "admin_a_token", "/visa/{{s18_visa1_id}}", "'VISA0000001'", ""),
            read("S18N.26 AC4: tenant A's first incident keeps INC0000001", "admin_a_token", "/incident/{{s18_inc_a1_id}}", "'INC0000001'", ""),
            req("S18N.27 AC5: admin@tenant-b reads tenant A's format: 404", "GET", nf + "/{{s18n_visa_fmt}}", auth="admin_b_token",
                tests=no404 + "\nbru.setVar('s18n_404_a', N.text());\nN.noLeak(bru.getVar('s18n_visa_fmt'), '{yyyy}');"),
            req("S18N.28 AC5: admin@tenant-b reads a made-up id: the same 404, byte for byte", "GET", nf + "/" + ghost, auth="admin_b_token",
                tests=no404 + "\ntest('the same body as for tenant A\\'s format', () => expect(N.text()).to.eql(bru.getVar('s18n_404_a')));"),
            problem_req("S18N.29 AC5: admin@tenant-b links tenant A's format to tenant B's incident type: 422 number_format_not_found", "POST",
                        et + "/incident/versions", "number_format_not_found", 422, auth="admin_b_token", headers=key("b-link"), body={},
                        pre=link_pre("admin_b_token", "incident", "{ id: bru.getVar('s18n_visa_fmt'), version: 1 }"),
                        extra="bru.setVar('s18n_422_a', JSON.stringify({ detail: N.json().detail, errors: N.json().errors }));\nN.noLeak('{yyyy}');"),
            problem_req("S18N.30 AC5: a made-up format id gives the same 422", "POST", et + "/incident/versions", "number_format_not_found", 422,
                        auth="admin_b_token", headers=key("b-ghost"), body={},
                        pre=link_pre("admin_b_token", "incident", "{ id: '%s', version: 1 }" % ghost),
                        extra="test('the same detail and errors as for tenant A\\'s format', () => expect(JSON.stringify({ detail: N.json().detail, errors: N.json().errors })).to.eql(bru.getVar('s18n_422_a')));"),
            inc("S18N.31 AC5: tenant B's incident type still numbers by default: INC0000004", "inc-b4", "admin_b_token", "INC0000004", ""),
            fmt("S18N.32 E9: admin@tenant-a writes {prefix}-{seq:1} (refuse), nine numbers", "tiny", "{prefix}-{seq:1}", "refuse", "s18n_tiny_fmt",
                "A one-digit sequence: PMT-1 to PMT-9, then nothing left."),
            req("S18N.33 E9: admin@tenant-a links it to the permit type", "POST", et + "/permit/versions", auth="admin_a_token", headers=key("tiny-link"),
                body={"definition": S18N_DEF, "number_format": {"id": "{{s18n_tiny_fmt}}", "version": 1}},
                tests="N.status(201);\ntest('pins the format', () => expect(N.json().number_format).to.eql({ id: bru.getVar('s18n_tiny_fmt'), version: 1 }));"),
            req("S18N.34 E9: fill the format: PMT-1 to PMT-9", "GET", et + "/permit", auth="admin_a_token", pre=S18N_FILL,
                desc="The pre-request script creates nine permits one after the other; this request reads the type.",
                tests="""N.status(200);
const rs = JSON.parse(bru.getVar('s18n_fill'));
test(`9 creates: ${rs.map(r => r.status + ' ' + r.number).join(', ')}`, () => expect(rs.map(r => r.number)).to.eql(['PMT-1', 'PMT-2', 'PMT-3', 'PMT-4', 'PMT-5', 'PMT-6', 'PMT-7', 'PMT-8', 'PMT-9']));
bru.setVar('s18n_pmt1_id', rs[0].id);"""),
            problem_req("S18N.35 E9: one more permit: 409 number_space_exhausted", "POST", rec + "/permit", "number_space_exhausted", 409,
                        auth="admin_a_token", headers=key("exhausted"), body=body("one too many"),
                        desc="The format is full: nothing is created, and one audit entry is written."),
            req("S18N.36 E9: the permit type's audit timeline has exactly one number_space_exhausted entry", "GET",
                audit + "?subject_type=entity_definition&subject_id={{s18n_permit_def}}&limit=500", auth="admin_a_token", pre=S18N_PERMIT_DEF,
                desc="`subject_type=entity_definition`, `subject_id` the permit type (found through PMT-1's create entry).",
                tests=S18N_EXHAUSTED),
            req("S18N.37 E9: tenant B's timeline has no number_space_exhausted entry", "GET", audit + "?domain=record&limit=500", auth="admin_b_token",
                desc="admin@tenant-b reads tenant B's record timeline. It is not empty (tenant B's incident creates are on it), so the check reads a real page.",
                tests="""N.status(200);
const items = N.json().items;
test(`tenant B's record timeline has entries (${(items || []).length})`, () => {
  expect(items).to.be.an('array').that.is.not.empty;
  expect(items.map(e => e.action)).to.include('create');
});
test('no number_space_exhausted entry', () => expect(items.filter(e => e.action === 'number_space_exhausted')).to.eql([]));
N.noLeak(bru.getVar('s18n_permit_def'));"""),
            req("S18N.38 E9: admin@tenant-b asks for tenant A's permit type's timeline: an empty page", "GET",
                audit + "?subject_type=entity_definition&subject_id={{s18n_permit_def}}&limit=500", auth="admin_b_token",
                desc="The same filter as S18N.36, as tenant B's admin. The tenant comes from the token, so tenant A's entry is not there.",
                tests="N.status(200);\ntest('no entries', () => expect(N.json().items).to.eql([]));"),
        ],
    }


# --------------------------------------------------------------------------- S30
def s30():
    """Story S30 (TICK-935, kit TICK-944 P11-12): an admin composes incident
    access from named conditions with all, any and not. Walked as
    admin@tenant-a, agent@tenant-a (Alice, /service-desk) and
    requester@tenant-a (the seeded auditor@tenant-a.test), with Bob of tenant
    B for the isolation rows. The folder publishes its own documents and ends
    by republishing the policy it found (S30.47), so S10 and S30 run again on
    the same stack."""
    inc = "{{core_url}}/api/v1/records/incident"
    et = "{{core_url}}/api/v1/entity-types/incident/access"
    mp = {"Content-Type": "application/merge-patch+json"}
    key = lambda k: {"Idempotency-Key": "tick944-s30-{{s30_run}}-" + k}
    ex = lambda rec: "{{core_url}}/api/v1/access/explain?entity=incident&record={{%s}}&user={{s30_alice}}" % rec
    missing = inc + "/00000000-0000-4000-8000-00000000dead"
    no404 = """N.status(404);
test('problem+json, code not_found, no instance', () => {
  expect(N.header('Content-Type') || '').to.include('application/problem+json');
  expect(N.json().code).to.eql('not_found');
  expect(N.json()).to.not.have.property('instance');
});"""
    same404 = no404 + "\ntest('body byte-identical to the missing id\\'s 404', () => expect(N.text()).to.eql(bru.getVar('s30_ref404')));"
    created = lambda var: "N.status(201);\nbru.setVar('%s', N.json().id);" % var
    ids = "const ids = N.json().items.map(i => i.id);\n"
    has = lambda var: "test('includes %s', () => expect(ids).to.include(bru.getVar('%s')));\n" % (var, var)
    hasnt = lambda var: "test('leaves out %s', () => expect(ids).to.not.include(bru.getVar('%s')));\n" % (var, var)
    exact_total = """test('total is the number of items (one page, no cursor)', () => {
  expect(N.json().next_cursor, 'one page').to.eql(null);
  expect(N.json().total).to.eql(N.json().items.length);
});
"""
    # The list as a sorted id list and its total, kept before the upgrade
    # (AC5) and compared after it.
    keep_list = lambda var: "bru.setVar('%s', JSON.stringify({ ids: N.json().items.map(i => i.id).sort(), total: N.json().total }));" % var
    same_list = lambda var: """N.status(200);
const was = JSON.parse(bru.getVar('%s'));
test('the same ids as before the upgrade', () => expect(N.json().items.map(i => i.id).sort()).to.eql(was.ids));
test('the same total as before the upgrade', () => expect(N.json().total).to.eql(was.total));""" % var
    keep_code = lambda var: "bru.setVar('%s', JSON.stringify({ status: res.getStatus(), body: res.getStatus() === 404 ? N.text() : null }));" % var
    same_code = lambda var: """const was = JSON.parse(bru.getVar('%s'));
test('the same status as before the upgrade (' + was.status + ')', () => expect(res.getStatus()).to.eql(was.status));
if (was.status === 404) test('the same 404 bytes as before', () => expect(N.text()).to.eql(was.body));""" % var
    # The composed document (AC1). The pre-request scripts build it from the
    # group ids of this stack; variants change one part of it.
    doc_js = r"""
const SD = bru.getVar('s30_sd'), ADM = bru.getVar('s30_admins');
const inAssigned = { cmp: { column: 'assignment_group_id', op: 'in', caller: 'my_groups' } };
const doc = () => ({
  format: 2,
  conditions: [
    { name: 'in_assigned_group', expr: inAssigned },
    { name: 'is_requester', expr: { cmp: { column: 'requester_id', op: 'eq', caller: 'self' } } },
    { name: 'is_new', expr: { cmp: { column: 'state', op: 'eq', values: ['new'] } } },
  ],
  policies: [
    { name: 'admins', ops: ['read', 'write'], when: { member_of: { groups: [ADM] } } },
    { name: 'agents_see_group_not_raised', ops: ['read'],
      when: { all: [{ member_of: { groups: [SD] } }, { ref: 'in_assigned_group' }, { not: { ref: 'is_requester' } }] } },
    { name: 'agents_edit_group_new', ops: ['write'],
      when: { all: [{ member_of: { groups: [SD] } }, { ref: 'in_assigned_group' }, { ref: 'is_new' }] } },
    { name: 'requesters_see_own', ops: ['read'],
      when: { all: [{ not: { member_of: { groups: [SD] } } }, { ref: 'is_requester' }] } },
    { name: 'requesters_edit_own_new', ops: ['write'],
      when: { all: [{ not: { member_of: { groups: [SD] } } }, { ref: 'is_requester' }, { ref: 'is_new' }] } },
  ],
});
"""
    publish = lambda change, etag_var: LOAD_PRE + doc_js + """
const d = doc();
%s
req.setBody({ rules: d, masks: [] });
req.setHeader('If-Match', bru.getVar('%s'));
""" % (change, etag_var)
    problem_at = lambda rule, pointer: """N.problem('invalid_access_policy', 422);
const errs = N.json().errors || [];
test('%s at %s', () => expect(errs.map(e => e.pointer + ' ' + e.rule)).to.include('%s %s'));""" % (rule, pointer, pointer, rule)
    trace = lambda policy, cond, val: "test('trace: %s on %s is %s', () => expect(b.trace).to.deep.include({ condition: '%s', policy: '%s', value: %s }));\n" % (cond, policy, val, cond, policy, val)
    return {
        "dir": "S30", "name": "S30 composable access",
        "desc": "Story S30, TICK-935 (kit TICK-944, PLAN-011 P11-12). An admin composes the incident type's access from named conditions (`in_assigned_group`, `is_requester`, `is_new`) combined with `all`, `any` and `not` into named policies (ADR-010 format 2). AC1 S30.28 to S30.31, AC2 S30.32 to S30.35, AC3 S30.36 to S30.41, AC4 S30.42 and S30.43, AC5 S30.9 and S30.14 to S30.27; isolation S30.44 to S30.46. Needs `tools/seed.sh`. Story users: `admin@tenant-a` is tenant A's admin, `agent@tenant-a` is Alice (`/service-desk`), `requester@tenant-a` is the seeded `auditor@tenant-a.test`, Bob is tenant B's agent. Runs again on the same stack: S30.47 republishes the policy S30.9 read, so each pass adds four ACL versions and leaves the decisions as it found them. Kit: `docs/acceptance/S30/`.",
        "items": [
            token("S30.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s30_run', Math.random().toString(16).slice(2, 10));"),
            token("S30.2 Sign in as agent@tenant-a (Alice)", "alice_username", "alice_password", "alice_token"),
            token("S30.3 Sign in as requester@tenant-a (seeded auditor@tenant-a.test)", "auditor_a_username", "auditor_a_password", "req_a_token"),
            token("S30.4 Sign in as agent@tenant-b (Bob, tenant B)", "bob_username", "bob_password", "bob_token"),
            req("S30.5 Alice's principal id and groups", "GET", "{{core_url}}/api/v1/me", auth="alice_token",
                desc="Keeps Alice's `user_id`, her group ids and the id of `/service-desk`.",
                tests="""N.me('00000000-0000-4000-8000-0000000000a1');
bru.setVar('s30_alice', N.json().user_id);
bru.setVar('s30_alice_groups', JSON.stringify(N.json().groups));
const sd = N.json().group_paths.find(g => g.path === '/service-desk');
test('Alice is in /service-desk', () => expect(sd, 'group_paths /service-desk').to.be.an('object'));
bru.setVar('s30_sd', sd ? sd.id : '');"""),
            req("S30.6 The admin's admins group", "GET", "{{core_url}}/api/v1/me", auth="admin_a_token",
                tests="""N.me('00000000-0000-4000-8000-0000000000a1');
const g = N.json().group_paths.find(x => x.path === '/admins');
test('the admin is in /admins', () => expect(g, 'group_paths /admins').to.be.an('object'));
bru.setVar('s30_admins', g ? g.id : '');"""),
            req("S30.7 The requester's principal id: in neither /service-desk nor admins", "GET", "{{core_url}}/api/v1/me", auth="req_a_token",
                tests="""N.me('00000000-0000-4000-8000-0000000000a1');
bru.setVar('s30_req', N.json().user_id);
test('not in /service-desk or /admins', () => {
  expect(N.paths()).to.not.include('/service-desk');
  expect(N.paths()).to.not.include('/admins');
});"""),
            req("S30.8 Bob's /service-desk group: a group of tenant B", "GET", "{{core_url}}/api/v1/me", auth="bob_token",
                desc="Its id is the other tenant's group id that S30.34 tries to publish in tenant A.",
                tests="""N.me('00000000-0000-4000-8000-0000000000b1');
const sd = N.json().group_paths.find(g => g.path === '/service-desk');
test('Bob is in /service-desk of tenant B', () => expect(sd).to.be.an('object'));
bru.setVar('s30_b_sd', sd ? sd.id : '');"""),
            req("S30.9 AC5: the admin reads the incident policy: the S10 rules come out as format 2", "GET", et, auth="admin_a_token",
                desc="On a fresh stack this is version 1, the default incident ACL: the four S10 rules (`onboard.DefaultIncidentRules`) that `tools/seed.sh` publishes through `nava-onboard reconcile-default-acl`. Since TICK-939 that path stores them as format 2 (`run.sh` shows `jsonb_typeof` `object`), as policies named after the rule ids with `-` turned into `_`. A row stored as format 1 before TICK-939 reads back the same way, converted, with the rule id kept as `legacy_id`. Kept for S30.21 and S30.47.",
                tests="""N.status(200);
const b = N.json();
test('rules is a format-2 document', () => {
  expect(b.rules.format).to.eql(2);
  expect(b.rules.conditions).to.be.an('array');
  expect(b.rules.policies).to.be.an('array').that.is.not.empty;
});
test('every policy has a valid name, ops and a when tree', () => b.rules.policies.forEach(p => {
  expect(p.name).to.match(/^[a-z][a-z0-9_]{0,62}$/);
  expect(p.ops).to.be.an('array');
  expect(p.when).to.be.an('object');
}));
if (b.version === 1) test('version 1 is the S10 default: default_admins, default_service_desk, default_requester, default_requester_new', () => {
  expect(b.rules.policies.map(p => p.name)).to.eql(['default_admins', 'default_service_desk', 'default_requester', 'default_requester_new']);
  const legacy = b.rules.policies.map(p => p.legacy_id);
  // Seeded since TICK-939 as format 2 (no legacy_id); a row stored as format 1 before it reads back converted, keeping the rule id.
  expect([JSON.stringify([undefined, undefined, undefined, undefined]), JSON.stringify(['default-admins', 'default-service-desk', 'default-requester', 'default-requester-new'])]).to.include(JSON.stringify(legacy));
});
test('ETag W/"<version>"', () => expect(N.header('ETag')).to.eql('W/"' + b.version + '"'));
bru.setVar('s30_policy', JSON.stringify(b));
bru.setVar('s30_etag', N.header('ETag'));"""),
            req("S30.10 The admin creates an incident in /service-desk raised by the requester", "POST", inc, auth="admin_a_token",
                headers=key("sd-other"), body={"data": {"short_description": "S30 {{s30_run}} service-desk, raised by the requester",
                                                         "assignment_group": "{{s30_sd}}", "requester": "{{s30_req}}"}},
                tests=created("s30_sd_other")),
            req("S30.11 The admin creates an incident in /service-desk raised by Alice", "POST", inc, auth="admin_a_token",
                headers=key("sd-mine"), body={"data": {"short_description": "S30 {{s30_run}} service-desk, raised by Alice",
                                                        "assignment_group": "{{s30_sd}}", "requester": "{{s30_alice}}"}},
                tests=created("s30_sd_mine")),
            req("S30.12 The admin creates an incident in admins raised by the requester", "POST", inc, auth="admin_a_token",
                headers=key("adm"), body={"data": {"short_description": "S30 {{s30_run}} admins, raised by the requester",
                                                    "assignment_group": "{{s30_admins}}", "requester": "{{s30_req}}"}},
                tests=created("s30_adm")),
            req("S30.13 Alice opens an id that does not exist: the reference 404", "GET", missing, auth="alice_token",
                tests=no404 + "\nbru.setVar('s30_ref404', N.text());"),
            req("S30.14 AC5 before: Alice's list under the stored S10 rules", "GET", inc + "?limit=200", auth="alice_token",
                desc="`default_service_desk` and `default_requester` admit both /service-desk incidents, not the admins one.",
                tests="N.status(200);\n" + ids + has("s30_sd_other") + has("s30_sd_mine") + hasnt("s30_adm") + exact_total + keep_list("s30_f1_alice")),
            req("S30.15 AC5 before: the requester's list", "GET", inc + "?limit=200", auth="req_a_token",
                tests="N.status(200);\n" + ids + has("s30_sd_other") + has("s30_adm") + hasnt("s30_sd_mine") + exact_total + keep_list("s30_f1_req")),
            req("S30.16 AC5 before: Alice opens the incident she raised", "GET", inc + "/{{s30_sd_mine}}", auth="alice_token",
                tests="N.status(200);\n" + keep_code("s30_f1_a_mine")),
            req("S30.17 AC5 before: Alice opens the admins incident", "GET", inc + "/{{s30_adm}}", auth="alice_token",
                tests=same404 + "\n" + keep_code("s30_f1_a_adm")),
            req("S30.18 AC5 before: the requester opens its /service-desk incident", "GET", inc + "/{{s30_sd_other}}", auth="req_a_token",
                tests="N.status(200);\n" + keep_code("s30_f1_r_other")),
            req("S30.19 AC5 before: the requester opens Alice's incident", "GET", inc + "/{{s30_sd_mine}}", auth="req_a_token",
                tests="N.status(404);\n" + keep_code("s30_f1_r_mine")),
            req("S30.20 AC5 before: Alice opens the requester's /service-desk incident", "GET", inc + "/{{s30_sd_other}}", auth="alice_token",
                tests="N.status(200);\n" + keep_code("s30_f1_a_other")),
            req("S30.21 AC5: the admin republishes the format-2 document GET returned", "PUT", et, auth="admin_a_token",
                headers=key("upgrade"), body={"rules": {}},
                pre=LOAD_PRE + r"""
const cur = JSON.parse(bru.getVar('s30_policy'));
req.setBody({ rules: cur.rules, masks: cur.masks });
req.setHeader('If-Match', 'W/"' + cur.version + '"');
""",
                desc="The body is S30.9's `rules`, unchanged, sent through the access route as a format-2 body. S30.22 to S30.27 repeat S30.14 to S30.19 on the new version and must give the same answers.",
                tests="""N.status(200);
const was = JSON.parse(bru.getVar('s30_policy'));
test('version + 1', () => expect(N.json().version).to.eql(was.version + 1));
test('the same document back', () => expect(N.json().rules).to.eql(was.rules));
bru.setVar('s30_etag', N.header('ETag'));"""),
            req("S30.22 AC5 after: Alice's list is the same", "GET", inc + "?limit=200", auth="alice_token", tests=same_list("s30_f1_alice")),
            req("S30.23 AC5 after: the requester's list is the same", "GET", inc + "?limit=200", auth="req_a_token", tests=same_list("s30_f1_req")),
            req("S30.24 AC5 after: Alice opens the incident she raised", "GET", inc + "/{{s30_sd_mine}}", auth="alice_token", tests=same_code("s30_f1_a_mine")),
            req("S30.25 AC5 after: Alice opens the admins incident", "GET", inc + "/{{s30_adm}}", auth="alice_token", tests=same_code("s30_f1_a_adm")),
            req("S30.26 AC5 after: the requester opens its /service-desk incident", "GET", inc + "/{{s30_sd_other}}", auth="req_a_token", tests=same_code("s30_f1_r_other")),
            req("S30.27 AC5 after: the requester opens Alice's incident", "GET", inc + "/{{s30_sd_mine}}", auth="req_a_token", tests=same_code("s30_f1_r_mine")),
            req("S30.28 AC1: the admin publishes \"agents see tickets in their group that they did not raise\"", "PUT", et, auth="admin_a_token",
                headers=key("composed"), body={"rules": {}}, pre=publish("", "s30_etag"),
                desc="Three named conditions and five policies. `agents_see_group_not_raised` is `member_of /service-desk AND in_assigned_group AND NOT is_requester`. Requesters outside `/service-desk` see and, while `new`, edit their own. The `not` over `is_requester` is accepted with the lint `not_over_caller_leaf` (a caller with no id would pass it; every signed-in user has one).",
                tests="""N.status(200);
const b = N.json();
test('stored as published: 3 conditions, 5 policies', () => {
  expect(b.rules.conditions.map(c => c.name)).to.eql(['in_assigned_group', 'is_requester', 'is_new']);
  expect(b.rules.policies.map(p => p.name)).to.eql(['admins', 'agents_see_group_not_raised', 'agents_edit_group_new', 'requesters_see_own', 'requesters_edit_own_new']);
});
test('lint not_over_caller_leaf on the not', () => expect((b.warnings || []).map(w => w.pointer + ' ' + w.code)).to.include('/rules/policies/1/when/all/2/not not_over_caller_leaf'));
bru.setVar('s30_composed', JSON.stringify(b));
bru.setVar('s30_etag', N.header('ETag'));"""),
            req("S30.29 AC1: Alice's list is exactly her groups' incidents she did not raise", "GET", inc + "?limit=200", auth="alice_token",
                tests="N.status(200);\n" + ids + has("s30_sd_other") + hasnt("s30_sd_mine") + hasnt("s30_adm") + exact_total + """
test('every item: one of her groups, and she is not the requester', () => {
  const mine = JSON.parse(bru.getVar('s30_alice_groups'));
  N.json().items.forEach(i => {
    expect(i.assignment_group && mine.includes(i.assignment_group.id), i.number + ' in her groups').to.eql(true);
    expect(i.data.requester, i.number + ' requester').to.not.eql(bru.getVar('s30_alice'));
  });
});"""),
            req("S30.30 AC1: Alice opens the incident she raised: the same 404 as a missing id", "GET", inc + "/{{s30_sd_mine}}", auth="alice_token",
                tests=same404),
            req("S30.31 AC1: the requester still sees its own incidents", "GET", inc + "?limit=200", auth="req_a_token",
                tests="N.status(200);\n" + ids + has("s30_sd_other") + has("s30_adm") + hasnt("s30_sd_mine") + exact_total + """
test('every item: raised by the requester', () => N.json().items.forEach(i => expect(i.data.requester).to.eql(bru.getVar('s30_req'))));"""),
            req("S30.32 AC2: a reference to an unknown condition: 422 at the ref", "PUT", et, auth="admin_a_token",
                headers=key("unknown-ref"), body={"rules": {}},
                pre=publish("d.policies[1].when.all[1] = { ref: 'in_asigned_group' };", "s30_etag"),
                tests=problem_at("unresolved_ref", "/rules/policies/1/when/all/1/ref")),
            req("S30.33 AC2: a reference cycle: 422 at the ref that closes it", "PUT", et, auth="admin_a_token",
                headers=key("cycle"), body={"rules": {}},
                pre=publish("""d.conditions.push({ name: 'loop_a', expr: { all: [{ ref: 'is_new' }, { ref: 'loop_b' }] } });
d.conditions.push({ name: 'loop_b', expr: { any: [{ ref: 'is_requester' }, { ref: 'loop_a' }] } });
d.policies[1].when.all.push({ ref: 'loop_a' });""", "s30_etag"),
                desc="`loop_a` refers to `loop_b`, which refers back to `loop_a`.",
                tests="""N.problem('invalid_access_policy', 422);
const errs = (N.json().errors || []).map(e => e.pointer + ' ' + e.rule);
test('ref_cycle, pointing into loop_a or loop_b', () => expect(errs.filter(e => /^\\/rules\\/conditions\\/[34]\\/expr\\/.*\\/ref ref_cycle$/.test(e))).to.not.be.empty);"""),
            req("S30.34 AC2: another tenant's group id: 422 at the id", "PUT", et, auth="admin_a_token",
                headers=key("foreign"), body={"rules": {}},
                pre=publish("d.policies[1].when.all[0] = { member_of: { groups: [bru.getVar('s30_b_sd')] } };", "s30_etag"),
                desc="Bob's `/service-desk` is a group of tenant B. The answer is the same as for a group id of no tenant, so it says nothing about tenant B.",
                tests=problem_at("foreign_id", "/rules/policies/1/when/all/0/member_of/groups/0") + "\nN.noLeak(bru.getVar('s30_b_sd'));"),
            req("S30.35 AC2: GET still shows the S30.28 version", "GET", et, auth="admin_a_token",
                tests="""N.status(200);
const was = JSON.parse(bru.getVar('s30_composed'));
test('version unchanged', () => expect(N.json().version).to.eql(was.version));
test('document unchanged', () => expect(N.json().rules).to.eql(was.rules));"""),
            req("S30.36 AC3 before: Alice opens the admins incident: 404", "GET", inc + "/{{s30_adm}}", auth="alice_token", tests=same404),
            req("S30.37 AC3: the admin edits only the condition in_assigned_group, one publish", "PUT", et, auth="admin_a_token",
                headers=key("edit-cond"), body={"rules": {}},
                pre=publish("d.conditions[0].expr = { any: [inAssigned, { cmp: { column: 'assignment_group_id', op: 'in', values: [ADM] } }] };", "s30_etag"),
                desc="`in_assigned_group` becomes \"assigned to one of my groups, or to admins\" (an escalation group). Two policies use it: `agents_see_group_not_raised` (read) and `agents_edit_group_new` (write). Nothing else in the document changes.",
                tests="""N.status(200);
const was = JSON.parse(bru.getVar('s30_composed'));
const b = N.json();
test('one new version', () => expect(b.version).to.eql(was.version + 1));
test('policies unchanged', () => expect(b.rules.policies).to.eql(was.rules.policies));
test('only in_assigned_group changed', () => {
  expect(b.rules.conditions[0].expr).to.not.eql(was.rules.conditions[0].expr);
  expect(b.rules.conditions.slice(1)).to.eql(was.rules.conditions.slice(1));
});
bru.setVar('s30_etag', N.header('ETag'));"""),
            req("S30.38 AC3: Alice's list now has the admins incident too", "GET", inc + "?limit=200", auth="alice_token",
                desc="The read policy `agents_see_group_not_raised` follows the edited condition.",
                tests="N.status(200);\n" + ids + has("s30_sd_other") + has("s30_adm") + hasnt("s30_sd_mine") + exact_total),
            req("S30.39 AC3: Alice opens the admins incident: 200", "GET", inc + "/{{s30_adm}}", auth="alice_token",
                tests="N.status(200);\nbru.setVar('s30_adm_etag', N.header('ETag'));"),
            req("S30.40 AC3: Alice edits it: 200", "PATCH", inc + "/{{s30_adm}}", auth="alice_token",
                headers={**key("alice-edit-adm"), **mp, "If-Match": "{{s30_adm_etag}}"}, body={"data": {"priority": 2}},
                desc="The write policy `agents_edit_group_new` follows the same edited condition: the incident is `new` and now \"in her assigned group\".",
                tests="N.status(200);"),
            req("S30.41 AC3: she still cannot open the incident she raised", "GET", inc + "/{{s30_sd_mine}}", auth="alice_token", tests=same404),
            req("S30.42 AC4: explain (Alice, the requester's /service-desk incident): the policy and its conditions", "GET", ex("s30_sd_other"),
                auth="admin_a_token",
                desc="`policy` is the first policy in declared order that grants read; `trace` lists each named condition it reached with its value on this incident.",
                tests="""N.status(200);
const b = N.json();
test('allow', () => expect(b.decision).to.eql('allow'));
test('policy agents_see_group_not_raised', () => expect(b.policy).to.eql('agents_see_group_not_raised'));
test('rule_id is the policy name', () => expect(b.rule_id).to.eql('agents_see_group_not_raised'));
test('acl_version is the S30.37 version', () => expect('W/"' + b.acl_version + '"').to.eql(bru.getVar('s30_etag')));
""" + trace("agents_see_group_not_raised", "in_assigned_group", "true") + trace("agents_see_group_not_raised", "is_requester", "false") + """
test('no voided policy', () => expect(b.invalid).to.eql([]));"""),
            req("S30.43 AC4: explain (Alice, the incident she raised): deny, and why", "GET", ex("s30_sd_mine"), auth="admin_a_token",
                desc="On a deny the trace covers every valid read policy, so the admin sees `is_requester` true where it decided.",
                tests="""N.status(200);
const b = N.json();
test('deny', () => expect(b.decision).to.eql('deny'));
test('no policy', () => expect(b.policy == null).to.eql(true));
""" + trace("agents_see_group_not_raised", "in_assigned_group", "true") + trace("agents_see_group_not_raised", "is_requester", "true")),
            req("S30.44 Isolation: Bob's incident list has none of tenant A's", "GET", inc + "?limit=200", auth="bob_token",
                tests="N.status(200);\n" + ids + hasnt("s30_sd_other") + hasnt("s30_sd_mine") + hasnt("s30_adm")),
            req("S30.45 Isolation: Bob opens tenant A's incident: 404", "GET", inc + "/{{s30_sd_other}}", auth="bob_token", tests=no404),
            req("S30.46 Isolation: Bob publishes incident access in tenant B: 403", "PUT", et, auth="bob_token",
                headers={**key("bob"), "If-Match": 'W/"1"'}, body={"rules": {"format": 2, "conditions": [], "policies": []}},
                desc="Bob is not a tenant admin; the admin check comes first, so nothing is checked, published or told.",
                tests="N.problem('forbidden', 403);"),
            req("S30.47 The admin republishes the policy S30.9 read", "PUT", et, auth="admin_a_token",
                headers=key("restore"), body={"rules": {}},
                pre=LOAD_PRE + r"""
const cur = JSON.parse(bru.getVar('s30_policy'));
req.setBody({ rules: cur.rules, masks: cur.masks });
req.setHeader('If-Match', bru.getVar('s30_etag'));
""",
                desc="Leaves the decisions as S30.9 found them, so S10 and S30 run again on this stack.",
                tests="""N.status(200);
test('the S30.9 document', () => expect(N.json().rules).to.eql(JSON.parse(bru.getVar('s30_policy')).rules));"""),
        ],
    }


# --------------------------------------------------------------------------- S32
def s32():
    """Story S32 (TICK-955, kit TICK-958 P11-24): a workflow condition step
    tests a named access policy (ADR-010 D9). One workflow key, `s32_route`,
    gets a version per criterion, so exactly one is current at a time. Walked
    as admin@tenant-a, agent@tenant-a (Alice, the assignee),
    requester@tenant-a (the seeded auditor@tenant-a.test) and admin@tenant-b
    (seeded by docs/acceptance/S18/tools/kit.mjs admin-b). The folder ends by
    making `s32_route` a no-op and republishing both tenants' incident access
    as it found them, so other folders and a second pass run on the same
    stack."""
    inc = "{{core_url}}/api/v1/records/incident"
    et = "{{core_url}}/api/v1/entity-types/incident"
    acc = et + "/access"
    wf = "{{core_url}}/api/v1/workflow-definitions/s32_route/versions"
    audit = "{{core_url}}/api/v1/audit/entries?domain=config&subject_type=acl_policy&from={{s32_t0}}&limit=500"
    key = lambda k: {"Idempotency-Key": "tick958-s32-{{s32_run}}-" + k}
    placeholder = {"rules": "set by the pre-request script (built from this stack's group ids)"}

    def route(policy, timer=None):
        """The S32 workflow: on create, optionally wait, then test whether the
        incident's assignee may write it under `policy`."""
        steps = []
        if timer:
            steps.append({"key": "wait", "type": "timer", "duration": timer, "next": "check"})
        steps += [
            {"key": "check", "type": "condition", "policy": {"entity_type": "incident", "name": policy},
             "who": "assignee", "op": "write", "then": "triaged", "else": "needs_owner"},
            {"key": "triaged", "type": "update_record", "set": {"state": "triaged"}, "next": "done"},
            {"key": "needs_owner", "type": "update_record", "set": {"state": "needs_owner"}, "next": "done"},
            {"key": "done", "type": "end"},
        ]
        return {"format": "nava.workflow/v1", "trigger": {"on": "record.created", "entity": "incident"},
                "start": "wait" if timer else "check", "steps": steps}

    published = """N.status(201);
const b = N.json();
test('current, on incident', () => { expect(b.current).to.eql(true); expect(b.entity).to.eql('incident'); });
bru.setVar('s32_wf_version', String(b.version));"""

    def create(tag, assignee):
        return {"data": {"short_description": "S32 {{s32_run}} " + tag, "assignment_group": "{{s32_sd}}",
                         "requester": "{{s32_req}}", "assignee": "{{%s}}" % assignee}}

    def created(var):
        return """N.status(201);
const b = N.json();
test('state new', () => expect(b.state).to.eql('new'));
bru.setVar('%s', b.id);
bru.setVar('%s_at', String(Date.now()));""" % (var, var)

    # Waits until the record leaves `new` (the workflow wrote it) or 120 s
    # pass, then the request reads it once more.
    def wait_routed(var):
        return LOAD_PRE + """
const t0 = Number(bru.getVar('%s_at')) || 0;
for (;;) {
  const r = await N.send({ url: N.url('{{core_url}}/api/v1/records/incident/{{%s}}'), method: 'GET',
    headers: { Authorization: 'Bearer ' + bru.getVar('admin_a_token') }, timeout: 15000 }).catch(() => ({ status: 0, data: {} }));
  if (!bru.getVar('%s') || (r.status === 200 && r.data.state !== 'new') || Date.now() - t0 > 120 * 1000) break;
  await bru.sleep(500);
}
bru.setVar('%s_routed_at', String(Date.now()));""" % (var, var, var, var)

    def routed(state, var):
        return """N.status(200);
const b = N.json();
test('state %s, written by the workflow (version 2)', () => {
  expect(b.state).to.eql('%s');
  expect(b.version).to.eql(2);
});
console.log('%s routed to', b.state, 'after', ((Number(bru.getVar('%s_routed_at')) - Number(bru.getVar('%s_at'))) / 1000).toFixed(1), 's');""" % (state, state, var, var, var)

    # Tenant A's incident access for S32: admins, agents read, `agents_write`
    # (write for /service-desk; AC2 narrows it to the admins group alone) and
    # requesters read their own.
    doc_a = lambda writers: LOAD_PRE + """
const SD = bru.getVar('s32_sd'), ADM = bru.getVar('s32_admins');
const rules = {
  format: 2,
  conditions: [{ name: 'is_requester', expr: { cmp: { column: 'requester_id', op: 'eq', caller: 'self' } } }],
  policies: [
    { name: 'admins', ops: ['read', 'write'], when: { member_of: { groups: [ADM] } } },
    { name: 'agents_read', ops: ['read'], when: { member_of: { groups: [SD] } } },
    { name: 'agents_write', ops: ['write'], when: { member_of: { groups: [%s] } } },
    { name: 'requesters_see_own', ops: ['read'], when: { ref: 'is_requester' } },
  ],
};
req.setBody({ rules, masks: [] });
req.setHeader('If-Match', bru.getVar('s32_etag'));""" % writers
    acc_ok = """N.status(200);
const b = N.json();
test('agents_write grants write to %s', () => {
  const p = b.rules.policies.find(x => x.name === 'agents_write');
  expect(p.ops).to.eql(['write']);
  expect(p.when).to.eql({ member_of: { groups: [bru.getVar('%s')] } });
});
// Only a published version moves the ETag: after a refused PUT the restore keeps the last good one.
if (res.getStatus() === 200) bru.setVar('s32_etag', N.header('ETag'));
bru.setVar('%s', String(Date.now()));"""

    # A refused reference's audit entry: the reference is not stored, its
    # SHA-256 is (content_sha256 of "<entity_type>/<name>").
    def refused_entry(name, var):
        return """N.status(200);
const items = N.json().items;
const want = N.sha256('incident/%s');
const mine = items.filter(e => e.action === 'policy_ref_refused' && e.content_sha256 === want);
test('a policy_ref_refused entry whose content_sha256 is SHA-256("incident/%s")', () => expect(mine.length).to.be.above(0));
const e = mine[mine.length - 1] || {};
test('domain config, subject acl_policy, actor system workflow, source workflow', () => {
  expect(e.domain).to.eql('config');
  expect(e.subject_type).to.eql('acl_policy');
  expect(e.actor_system).to.eql('workflow');
  expect(e.actor_principal_id == null).to.eql(true);
  expect(e.source).to.eql('workflow');
});
const pubs = items.filter(x => x.actor_principal_id === bru.getVar('s32_admin'));
test('its subject is the incident access policy: the subject of the admin\\'s own access publishes', () => {
  expect(pubs.length).to.be.above(0);
  expect(e.subject_id).to.eql(pubs[0].subject_id);
  expect(e.entity_definition_id).to.eql(pubs[0].subject_id);
});
test('written after the record was created', () => expect(Date.parse(e.occurred_at)).to.be.at.least(Number(bru.getVar('%s_at')) - 2000));
bru.setVar('%s_entry', JSON.stringify({ action: e.action, domain: e.domain, subject_type: e.subject_type, subject_id: e.subject_id, actor_system: e.actor_system, source: e.source }));
console.log('%s entry', e.id, e.occurred_at, 'matching entries', mine.length);""" % (name, name, var, var, var)

    return {
        "dir": "S32", "name": "S32 workflow policy",
        "desc": "Story S32, TICK-955 (kit TICK-958, PLAN-011 P11-24, ADR-010 D9). A workflow `condition` step asks \"may this incident's assignee write it under policy X?\" and branches to `triaged` or `needs_owner`. One workflow key, `s32_route`, gets one version per criterion. AC1 S32.13 to S32.18, AC2 S32.19 to S32.24 (a 20-second timer step), AC3 S32.25 to S32.28, AC4 S32.29 to S32.36; restore S32.37 to S32.39. Needs `tools/seed.sh` and admin@tenant-b (`docs/acceptance/S18/tools/kit.mjs admin-b`, then one group sync); `docs/acceptance/S32/run.sh` does both. Story users: `admin@tenant-a`, `agent@tenant-a` is Alice (`/service-desk`, the assignee), `requester@tenant-a` is the seeded `auditor@tenant-a.test`, `admin@tenant-b` is tenant B's admin. Runs again on the same stack: the restore steps leave `s32_route` a no-op and both tenants' incident access as the folder found it. Kit: `docs/acceptance/S32/`.",
        "items": [
            token("S32.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
                  extra="bru.setVar('s32_run', Math.random().toString(16).slice(2, 10));\nbru.setVar('s32_t0', new Date(Date.now() - 5000).toISOString());\nconsole.log('S32 run', bru.getVar('s32_run'));"),
            token("S32.2 Sign in as agent@tenant-a (Alice)", "alice_username", "alice_password", "alice_token"),
            token("S32.3 Sign in as requester@tenant-a (seeded auditor@tenant-a.test)", "auditor_a_username", "auditor_a_password", "req_a_token"),
            token("S32.4 Sign in as admin@tenant-b", "admin_b_username", "admin_b_password", "admin_b_token",
                  desc="admin@tenant-b.test is seeded by `docs/acceptance/S18/tools/kit.mjs admin-b` (in organization tenant-b and `/t/<B>/admins`); `run.sh` runs it and one group sync."),
            req("S32.5 Alice's principal id and /service-desk", "GET", "{{core_url}}/api/v1/me", auth="alice_token",
                tests=f"""N.me('{A}');
bru.setVar('s32_alice', N.json().user_id);
const sd = N.json().group_paths.find(g => g.path === '/service-desk');
test('Alice is in /service-desk', () => expect(sd, 'group_paths /service-desk').to.be.an('object'));
bru.setVar('s32_sd', sd ? sd.id : '');"""),
            req("S32.6 The admin's principal id and admins group", "GET", "{{core_url}}/api/v1/me", auth="admin_a_token",
                tests=f"""N.me('{A}');
bru.setVar('s32_admin', N.json().user_id);
const g = N.json().group_paths.find(x => x.path === '/admins');
test('the admin is in /admins', () => expect(g, 'group_paths /admins').to.be.an('object'));
bru.setVar('s32_admins', g ? g.id : '');"""),
            req("S32.7 The requester's principal id: not in /service-desk", "GET", "{{core_url}}/api/v1/me", auth="req_a_token",
                tests=f"""N.me('{A}');
bru.setVar('s32_req', N.json().user_id);
test('not in /service-desk or /admins', () => {{
  expect(N.paths()).to.not.include('/service-desk');
  expect(N.paths()).to.not.include('/admins');
}});"""),
            req("S32.8 admin@tenant-b is tenant B's admin", "GET", "{{core_url}}/api/v1/me", auth="admin_b_token",
                tests=f"""N.me('{B}');
const g = N.json().group_paths.find(x => x.path === '/admins');
test('admin@tenant-b is in /admins of tenant B', () => expect(g, 'group_paths /admins').to.be.an('object'));
bru.setVar('s32_b_admins', g ? g.id : '');"""),
            req("S32.9 The admin reads the incident type", "GET", et, auth="admin_a_token",
                desc="Kept for S32.10, which adds the two states the S32 workflow writes.",
                tests="""N.status(200);
const b = N.json();
test('the incident type, current', () => { expect(b.key).to.eql('incident'); expect(b.current).to.eql(true); });
bru.setVar('s32_cur_schema', N.rawMember(N.text(), 'schema'));
bru.setVar('s32_fixed', JSON.stringify(b.fixed_columns));
bru.setVar('s32_states', JSON.stringify(b.states));
bru.setVar('s32_has_states', String(['triaged', 'needs_owner'].every(s => b.states.states.includes(s))));"""),
            req("S32.10 The admin adds the states triaged and needs_owner: 201", "POST", et + "/versions", auth="admin_a_token",
                headers=key("states"), body={"definition": "set by the pre-request script (the current incident version plus two states)"},
                pre=LOAD_PRE + r"""
if (bru.getVar('s32_has_states') === 'true') { bru.runner.skipRequest(); }
const schema = JSON.parse(bru.getVar('s32_cur_schema'));
const states = JSON.parse(bru.getVar('s32_states'));
for (const s of ['triaged', 'needs_owner']) {
  states.states.push(s);
  states.transitions.push({ from: 'new', to: s });
  schema.properties.state.enum.push(s);
}
req.setBody({ definition: { schema, fixed_columns: JSON.parse(bru.getVar('s32_fixed')), states } });""",
                desc="The story's workflow sets `state` to `triaged` or `needs_owner`, which the seeded incident type does not have. Two states and the transitions `new -> triaged` and `new -> needs_owner`: a compatible version. Skipped when the type already has them (a second pass).",
                tests="""N.status(201);
const b = N.json();
test('current, with triaged and needs_owner', () => {
  expect(b.current).to.eql(true);
  expect(b.states.states).to.include.members(['triaged', 'needs_owner']);
});"""),
            req("S32.11 The admin reads the incident access policy", "GET", acc, auth="admin_a_token",
                desc="Kept for S32.39, which republishes it.",
                tests="""N.status(200);
bru.setVar('s32_policy', JSON.stringify(N.json()));
bru.setVar('s32_etag', N.header('ETag'));"""),
            req("S32.12 The admin publishes access with agents_write for /service-desk", "PUT", acc, auth="admin_a_token",
                headers=key("acc-sd"), body=placeholder, pre=doc_a("SD"),
                desc="Four policies: `admins` (read, write), `agents_read` (read for `/service-desk`), `agents_write` (write for `/service-desk`) and `requesters_see_own` (read).",
                tests=acc_ok % ("/service-desk", "s32_sd", "s32_acc_sd_at")),
            req("S32.13 AC1: the admin publishes s32_route testing agents_write: 201", "POST", wf, auth="admin_a_token",
                headers=key("wf-ac1"), body=route("agents_write"),
                desc="On `record.created` of an incident: `check` is a condition step `{policy: {entity_type: incident, name: agents_write}, who: assignee, op: write}`; then `triaged`, else `needs_owner`.",
                tests=published),
            req("S32.14 AC1: the admin creates an incident assigned to Alice", "POST", inc, auth="admin_a_token",
                headers=key("ac1-alice"), body=create("AC1 assigned to Alice", "s32_alice"), tests=created("s32_ac1")),
            req("S32.15 AC1 control: an incident assigned to the requester", "POST", inc, auth="admin_a_token",
                headers=key("ac1-req"), body=create("AC1 assigned to the requester", "s32_req"), tests=created("s32_ac1_req"),
                desc="The requester is not in `/service-desk`, so `agents_write` does not grant it write: the same workflow takes the other branch."),
            req("S32.16 AC1: Alice's incident is routed to triaged", "GET", inc + "/{{s32_ac1}}", auth="admin_a_token",
                pre=wait_routed("s32_ac1"), desc="Waits up to 120 s after S32.14 for the workflow's write.",
                tests=routed("triaged", "s32_ac1")),
            req("S32.17 AC1 control: the requester's incident is routed to needs_owner", "GET", inc + "/{{s32_ac1_req}}", auth="admin_a_token",
                pre=wait_routed("s32_ac1_req"), tests=routed("needs_owner", "s32_ac1_req")),
            req("S32.18 AC1: the history shows the workflow's write", "GET", inc + "/{{s32_ac1}}/history", auth="admin_a_token",
                tests="""N.status(200);
const items = N.json().items;
test('newest: source workflow set state triaged; then the admin create', () => {
  expect(items[0].source).to.eql('workflow');
  expect(items[0].after.state).to.eql('triaged');
  expect(items[items.length - 1].action).to.eql('create');
});"""),
            req("S32.19 AC2: the admin publishes s32_route with a 20-second timer before the check: 201", "POST", wf, auth="admin_a_token",
                headers=key("wf-ac2"), body=route("agents_write", timer="PT20S"),
                desc="The same test, after a timer step `PT20S`. A run started now waits on the timer before it checks.",
                tests=published),
            req("S32.20 AC2: the admin creates an incident assigned to Alice", "POST", inc, auth="admin_a_token",
                headers=key("ac2-alice"), body=create("AC2 assigned to Alice, waiting", "s32_alice"), tests=created("s32_ac2")),
            req("S32.21 AC2: 3 s later it is still new: the run waits on its timer", "GET", inc + "/{{s32_ac2}}", auth="admin_a_token",
                pre="await bru.sleep(3000);",
                desc="`run.sh` shows from `workflow_ref` that the run had started before S32.22.",
                tests="""N.status(200);
test('state new, version 1', () => { expect(N.json().state).to.eql('new'); expect(N.json().version).to.eql(1); });"""),
            req("S32.22 AC2: the admin removes /service-desk from agents_write", "PUT", acc, auth="admin_a_token",
                headers=key("acc-narrow"), body=placeholder, pre=doc_a("ADM"),
                desc="`agents_write` now grants write to the admins group only. The waiting run has not checked yet.",
                tests=acc_ok % ("the admins group only", "s32_admins", "s32_narrowed_at") + """
test('published before the timer fires (within 20 s of the create)', () =>
  expect(Number(bru.getVar('s32_narrowed_at')) - Number(bru.getVar('s32_ac2_at'))).to.be.below(20000));"""),
            req("S32.23 AC2: once the timer fires, the waiting run routes to needs_owner", "GET", inc + "/{{s32_ac2}}", auth="admin_a_token",
                pre=wait_routed("s32_ac2"),
                desc="The run's check reads the current version of `agents_write`, the one S32.22 published.",
                tests=routed("needs_owner", "s32_ac2") + """
test('routed after the narrowing and after the timer', () => {
  expect(Number(bru.getVar('s32_ac2_routed_at'))).to.be.above(Number(bru.getVar('s32_narrowed_at')));
  expect(Number(bru.getVar('s32_ac2_routed_at')) - Number(bru.getVar('s32_ac2_at'))).to.be.at.least(19000);
});"""),
            req("S32.24 AC2: the admin gives agents_write back to /service-desk", "PUT", acc, auth="admin_a_token",
                headers=key("acc-sd-again"), body=placeholder, pre=doc_a("SD"),
                desc="So that in AC3 and AC4 only the policy name decides: Alice may write again under `agents_write`.",
                tests=acc_ok % ("/service-desk", "s32_sd", "s32_acc_sd2_at")),
            req("S32.25 AC3: the admin publishes s32_route naming does_not_exist: 201", "POST", wf, auth="admin_a_token",
                headers=key("wf-ac3"), body=route("does_not_exist"),
                desc="Publish does not look the policy up (D9: names resolve at run time), so it is accepted.",
                tests=published),
            req("S32.26 AC3: the admin creates an incident assigned to Alice", "POST", inc, auth="admin_a_token",
                headers=key("ac3-alice"), body=create("AC3 missing policy", "s32_alice"), tests=created("s32_ac3")),
            req("S32.27 AC3: the missing policy routes it to needs_owner", "GET", inc + "/{{s32_ac3}}", auth="admin_a_token",
                pre=wait_routed("s32_ac3"), desc="Alice may write under `agents_write` (S32.24), so the only reason for `needs_owner` is the missing name.",
                tests=routed("needs_owner", "s32_ac3")),
            req("S32.28 AC3: the admin finds the missing-policy entry in the audit log", "GET", audit, auth="admin_a_token",
                desc="How the admin finds it: list the audit log with `domain=config&subject_type=acl_policy` from the time of interest, and look for `action` `policy_ref_refused` (actor `workflow`, source `workflow`). Its `subject_id` is the incident type's access policy, the same subject as the admin's own access publishes. The entry does not hold the policy name; `content_sha256` is SHA-256 of `incident/does_not_exist`, so the admin matches it by hashing the name the workflow uses.",
                tests=refused_entry("does_not_exist", "s32_ac3")),
            req("S32.29 AC4: admin@tenant-b reads tenant B's incident access", "GET", acc, auth="admin_b_token",
                desc="Kept for S32.38, which republishes it.",
                tests="""N.status(200);
bru.setVar('s32_b_policy', JSON.stringify(N.json()));
bru.setVar('s32_b_etag', N.header('ETag'));"""),
            req("S32.30 AC4: admin@tenant-b adds a policy tenant_b_only to tenant B's incident type", "PUT", acc, auth="admin_b_token",
                headers=key("b-acc"), body=placeholder,
                pre=LOAD_PRE + r"""
const cur = JSON.parse(bru.getVar('s32_b_policy'));
const rules = JSON.parse(JSON.stringify(cur.rules));
rules.policies = rules.policies.filter(p => p.name !== 'tenant_b_only');
rules.policies.push({ name: 'tenant_b_only', ops: ['read', 'write'], when: { member_of: { groups: [bru.getVar('s32_b_admins')] } } });
req.setBody({ rules, masks: cur.masks });
req.setHeader('If-Match', bru.getVar('s32_b_etag'));""",
                desc="Tenant B's own incident type now has a policy `tenant_b_only` (read, write for tenant B's admins). Tenant A's incident type has no policy of that name.",
                tests="""N.status(200);
test('tenant B has tenant_b_only', () => expect(N.json().rules.policies.map(p => p.name)).to.include('tenant_b_only'));
if (res.getStatus() === 200) bru.setVar('s32_b_etag', N.header('ETag'));"""),
            req("S32.31 AC4: tenant A's admin publishes s32_route naming tenant_b_only: 201", "POST", wf, auth="admin_a_token",
                headers=key("wf-ac4"), body=route("tenant_b_only"), tests=published),
            req("S32.32 AC4: the admin creates an incident assigned to Alice", "POST", inc, auth="admin_a_token",
                headers=key("ac4-alice"), body=create("AC4 tenant B's policy", "s32_alice"), tests=created("s32_ac4")),
            req("S32.33 AC4: tenant B's policy is not found: needs_owner, as for a missing name", "GET", inc + "/{{s32_ac4}}", auth="admin_a_token",
                pre=wait_routed("s32_ac4"), desc="The run's check reads policies in tenant A's transaction only.",
                tests=routed("needs_owner", "s32_ac4")),
            req("S32.34 AC4: tenant A's audit has the same missing-policy entry as AC3", "GET", audit, auth="admin_a_token",
                tests=refused_entry("tenant_b_only", "s32_ac4") + """
test('the same action, domain, subject, actor and source as the AC3 entry', () =>
  expect(JSON.parse(bru.getVar('s32_ac4_entry'))).to.eql(JSON.parse(bru.getVar('s32_ac3_entry'))));"""),
            req("S32.35 AC4: tenant B's audit has no refused reference", "GET", audit, auth="admin_b_token",
                desc="The refusal is recorded in the tenant that ran the workflow, and tenant B's log names nothing of tenant A's.",
                tests="""N.status(200);
const items = N.json().items;
test('no policy_ref_refused entry in tenant B since S32.1', () => expect(items.filter(e => e.action === 'policy_ref_refused')).to.eql([]));
test('only tenant B\\'s own access publish (S32.30) is there', () => {
  expect(items.length).to.be.above(0);
  items.forEach(e => expect(e.subject_id).to.not.eql(JSON.parse(bru.getVar('s32_ac3_entry')).subject_id));
});"""),
            req("S32.36 AC4: naming another entity type's policy is refused at publish: 422", "POST",
                "{{core_url}}/api/v1/workflow-definitions/s32_other_type/versions", auth="admin_a_token",
                headers=key("wf-mismatch"),
                body={**route("tenant_b_only"), "steps": [{**s, "policy": {"entity_type": "request", "name": "tenant_b_only"}} if s["key"] == "check" else s for s in route("tenant_b_only")["steps"]]},
                desc="A policy test may only name the trigger entity's own type (`entity_type_mismatch`), whichever tenant has a type of that key, so a workflow cannot reach any other type's policies. Nothing is published.",
                tests="""N.problem('workflow_definition_invalid', 422);
test('entity_type_mismatch at the step\\'s policy entity_type', () =>
  expect((N.json().errors || []).map(e => e.pointer + ' ' + e.rule)).to.include('/steps/check/policy/entity_type entity_type_mismatch'));"""),
            req("S32.37 Restore: s32_route becomes a no-op: 201", "POST", wf, auth="admin_a_token",
                headers=key("wf-noop"),
                body={"format": "nava.workflow/v1", "trigger": {"on": "record.created", "entity": "incident"},
                      "start": "done", "steps": [{"key": "done", "type": "end"}]},
                desc="A definition cannot be deleted. Its current version now ends at once, so tenant A's later incidents keep their state.",
                tests=published),
            req("S32.38 Restore: admin@tenant-b republishes tenant B's access as S32.29 read it", "PUT", acc, auth="admin_b_token",
                headers=key("b-restore"), body=placeholder,
                pre=LOAD_PRE + r"""
const cur = JSON.parse(bru.getVar('s32_b_policy'));
req.setBody({ rules: cur.rules, masks: cur.masks });
req.setHeader('If-Match', bru.getVar('s32_b_etag'));""",
                tests="""N.status(200);
const was = JSON.parse(bru.getVar('s32_b_policy'));
test('the S32.29 rules', () => expect(N.json().rules).to.eql(was.rules));
test('the S32.29 masks', () => expect(N.json().masks).to.eql(was.masks));"""),
            req("S32.39 Restore: the admin republishes tenant A's access as S32.11 read it", "PUT", acc, auth="admin_a_token",
                headers=key("restore"), body=placeholder,
                pre=LOAD_PRE + r"""
const cur = JSON.parse(bru.getVar('s32_policy'));
req.setBody({ rules: cur.rules, masks: cur.masks });
req.setHeader('If-Match', bru.getVar('s32_etag'));""",
                tests="""N.status(200);
const was = JSON.parse(bru.getVar('s32_policy'));
test('the S32.11 rules', () => expect(N.json().rules).to.eql(was.rules));
test('the S32.11 masks', () => expect(N.json().masks).to.eql(was.masks));"""),
        ],
    }


# --------------------------------------------------------------------------- S31
S31_USERS = [
    # (token var, env user var, env password var, label)
    ("s31_agent_token", "agent_emea_username", "agent_emea_password", "agent-emea@tenant-a (in EMEA)"),
    ("s31_emea_token", "requester_emea_username", "requester_emea_password", "the requester in EMEA"),
    ("s31_de_token", "requester_germany_username", "requester_germany_password", "the requester in EMEA/Germany"),
    ("s31_apac_token", "requester_apac_username", "requester_apac_password", "the requester in APAC"),
    ("s31_none_token", "requester_none_username", "requester_none_password", "the requester in no unit"),
]


def _s31_common(prefix):
    """Shared S31 pieces: the incident URL, the missing-record 404 reference
    request (named with prefix), the byte-identical 404 check and the list
    helpers."""
    inc = "{{core_url}}/api/v1/records/incident"
    missing = inc + "/00000000-0000-4000-8000-00000000dead"
    no404 = """N.status(404);
test('problem+json, code not_found, no instance', () => {
  expect(N.header('Content-Type') || '').to.include('application/problem+json');
  expect(N.json().code).to.eql('not_found');
  expect(N.json()).to.not.have.property('instance');
});"""
    same404 = no404 + "\ntest('body byte-identical to the missing id\\'s 404', () => expect(N.text()).to.eql(bru.getVar('s31_ref404')));"
    ref404 = req(prefix + " Reference: a record id that does not exist is 404", "GET", missing, auth="s31_agent_token",
                 desc="The missing-record 404, kept to compare byte for byte with the 404 of a record the caller may not read.",
                 tests=no404 + "\nbru.setVar('s31_ref404', N.text());")
    ids = "const ids = N.json().items.map(i => i.id);\n"
    exact_total = """test('total is the number of items (one page, no cursor)', () => {
  expect(N.json().next_cursor, 'one page on a fresh stack').to.eql(null);
  expect(N.json().total).to.eql(N.json().items.length);
});
"""
    return inc, ref404, same404, ids, exact_total


def _s31_me(name, token, var):
    """GET /me for an S31 user: keeps the principal id. /me lists groups, not
    org units (ADR-010 D7 keeps units in org_units), so the unit memberships
    are shown from the database by run.sh."""
    t = f"""N.me('{A}');
bru.setVar('{var}', N.json().user_id);
test('in no /ou/ group and not in /service-desk or /admins', () => {{
  expect(N.paths().filter(p => p.startsWith('/ou/'))).to.eql([]);
  expect(N.paths()).to.not.include('/service-desk');
  expect(N.paths()).to.not.include('/admins');
}});"""
    return req(name, "GET", "{{core_url}}/api/v1/me", auth=token, tests=t)


def s31():
    """Story S31 (TICK-946, kit TICK-953 P11-20): a policy can say "tickets in
    my region" (ADR-010 D7, D8 as amended by ADR-010-A2). Part one, before the
    directory change: the region list and single reads (AC1), a ticket with
    no unit (AC2), another tenant's unit refused (AC5), the isolation rows,
    then the two directory changes of AC3 and AC4 in Keycloak. The group sync
    that applies them runs between this folder and `S31 region after sync`
    (docs/acceptance/S31/run.sh). Needs the realm's S31 directory (tenant A:
    /ou/EMEA, /ou/EMEA/Germany, /ou/APAC, agent-emea and the four
    requesters) and tools/seed.sh. One pass per fresh stack: the folder
    deletes EMEA/Germany in Keycloak."""
    inc, ref404, same404, ids, exact_total = _s31_common("S31.22")
    acc = "{{core_url}}/api/v1/entity-types/incident/access"
    key = lambda k: {"Idempotency-Key": "tick953-s31-{{s31_run}}-" + k}
    placeholder = {"rules": "set by the pre-request script (built from this stack's group ids)"}
    has = lambda var: "test('includes %s', () => expect(ids).to.include(bru.getVar('%s')));\n" % (var, var)
    hasnt = lambda var: "test('leaves out %s', () => expect(ids).to.not.include(bru.getVar('%s')));\n" % (var, var)

    def only_requesters(*vs):
        return "test('every item was raised by %s', () => N.json().items.forEach(i => expect([%s]).to.include(i.data.requester)));\n" % (
            " or ".join(vs), ", ".join("bru.getVar('%s')" % v for v in vs))

    # Tenant A's incident access for S31: admins read and write, and
    # in_my_region reads under `under` (caller, or a list of unit ids).
    doc = lambda under: LOAD_PRE + """
const ADM = bru.getVar('s31_admins');
const rules = {
  format: 2,
  conditions: [],
  policies: [
    { name: 'admins', ops: ['read', 'write'], when: { member_of: { groups: [ADM] } } },
    { name: 'in_my_region', ops: ['read'], when: { under: { of: %s } } },
  ],
};
req.setBody({ rules, masks: [] });
req.setHeader('If-Match', bru.getVar('s31_etag'));""" % under

    def create(n, tag, requester, var):
        return req(f"S31.{n} Setup: the admin creates an incident raised by {tag}", "POST", inc, auth="admin_a_token",
                   headers=key(var), body={"data": {"short_description": "S31 {{s31_run}} raised by " + tag, "requester": "{{%s}}" % requester}},
                   desc="The admin creates it with `requester` set. The platform stores the requester's primary unit with the ticket (ADR-010 D8); the body cannot name the unit.",
                   tests="N.status(201);\nbru.setVar('%s', N.json().id);\ntest('requester as sent', () => expect(N.json().data.requester).to.eql(bru.getVar('%s')));" % (var, requester))

    def listed(name, token, *, includes=(), excludes=(), requesters=(), empty=False, desc=""):
        t = "N.status(200);\n" + ids + "".join(has(v) for v in includes) + "".join(hasnt(v) for v in excludes) + exact_total
        if requesters:
            t += only_requesters(*requesters)
        if empty:
            t += "test('no incident at all: total 0', () => { expect(N.json().items).to.eql([]); expect(N.json().total).to.eql(0); });\n"
        t += "console.log('%s: total', N.json().total);" % name.split(" ")[0]
        return req(name, "GET", inc + "?limit=200", auth=token, desc=desc, tests=t)

    items = [
        token("S31.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
              extra="bru.setVar('s31_run', Math.random().toString(16).slice(2, 10));\nconsole.log('S31 run', bru.getVar('s31_run'));"),
    ]
    for i, (tok, u, p, label) in enumerate(S31_USERS, start=2):
        items.append(token(f"S31.{i} Sign in as {label}", u, p, tok))
    items += [
        token("S31.7 Sign in as agent@tenant-b (Bob, tenant B)", "bob_username", "bob_password", "bob_token"),
        req("S31.8 The admin's admins group", "GET", "{{core_url}}/api/v1/me", auth="admin_a_token",
            tests=f"""N.me('{A}');
const g = N.json().group_paths.find(x => x.path === '/admins');
test('the admin is in /admins', () => expect(g, 'group_paths /admins').to.be.an('object'));
bru.setVar('s31_admins', g ? g.id : '');"""),
        _s31_me("S31.9 agent-emea's principal id: in no agent group", "s31_agent_token", "s31_agent"),
        _s31_me("S31.10 The EMEA requester's principal id", "s31_emea_token", "s31_req_emea"),
        _s31_me("S31.11 The Germany requester's principal id", "s31_de_token", "s31_req_de"),
        _s31_me("S31.12 The APAC requester's principal id", "s31_apac_token", "s31_req_apac"),
        _s31_me("S31.13 The principal id of the requester with no unit", "s31_none_token", "s31_req_none"),
        req("S31.14 Bob: tenant B resolves", "GET", "{{core_url}}/api/v1/me", auth="bob_token",
            desc="The org unit ids S31.31 and S31.32 use come from the environment: `run.sh` reads tenant A's `EMEA` and tenant B's `eng/platform` from `org_units` and passes them as `s31_a_unit` and `s31_b_unit` (no API lists org units). By hand, set both in the `local` environment.",
            tests=f"""N.me('{B}');
test('the AC5 unit ids are set', () => {{ expect(N.v('s31_a_unit'), 's31_a_unit').to.match(/^[0-9a-f-]{{36}}$/); expect(N.v('s31_b_unit'), 's31_b_unit').to.match(/^[0-9a-f-]{{36}}$/); }});"""),
        req("S31.15 The admin reads the incident access policy", "GET", acc, auth="admin_a_token",
            desc="Keeps the ETag for S31.16.",
            tests="""N.status(200);
bru.setVar('s31_etag', N.header('ETag'));"""),
        req("S31.16 The admin publishes in_my_region: read a ticket whose unit is at or below one of mine", "PUT", acc, auth="admin_a_token",
            headers=key("acc"), body=placeholder, pre=doc("'caller'"),
            desc="Two policies: `admins` (read, write for `/admins`) and `in_my_region` (read, `{\"under\": {\"of\": \"caller\"}}`). Nobody else has any access to incidents, so whatever agent-emea and the requesters see below comes through `in_my_region`.",
            tests="""N.status(200);
test('in_my_region is under caller, read', () => {
  const p = N.json().rules.policies.find(x => x.name === 'in_my_region');
  expect(p.ops).to.eql(['read']);
  expect(p.when).to.eql({ under: { of: 'caller' } });
});
if (res.getStatus() === 200) bru.setVar('s31_etag', N.header('ETag'));"""),
        create(17, "the EMEA requester", "s31_req_emea", "s31_t_emea"),
        create(18, "the Germany requester", "s31_req_de", "s31_t_de"),
        create(19, "the APAC requester", "s31_req_apac", "s31_t_apac"),
        create(20, "the requester with no unit", "s31_req_none", "s31_t_none"),
        listed("S31.21 AC1: agent-emea lists exactly the EMEA and EMEA/Germany tickets", "s31_agent_token",
               includes=("s31_t_emea", "s31_t_de"), excludes=("s31_t_apac", "s31_t_none"), requesters=("s31_req_emea", "s31_req_de"),
               desc="The region is EMEA and every unit below it. `total` is counted under the same rule, so it is the number of listed items."),
        ref404,
        req("S31.23 AC1: agent-emea opens the APAC ticket by id: the missing-record 404", "GET", inc + "/{{s31_t_apac}}", auth="s31_agent_token",
            tests=same404),
        req("S31.24 AC1: agent-emea opens the Germany ticket by id: 200", "GET", inc + "/{{s31_t_de}}", auth="s31_agent_token",
            desc="The single read agrees with the list (ADR-010 I5).",
            tests="N.status(200);\ntest('the Germany ticket', () => expect(N.json().id).to.eql(bru.getVar('s31_t_de')));"),
        req("S31.25 AC2: agent-emea opens the no-unit ticket by id: the missing-record 404", "GET", inc + "/{{s31_t_none}}", auth="s31_agent_token",
            tests=same404),
        listed("S31.26 AC2: the EMEA requester's region: EMEA and Germany, not the no-unit ticket", "s31_emea_token",
               includes=("s31_t_emea", "s31_t_de"), excludes=("s31_t_apac", "s31_t_none"), requesters=("s31_req_emea", "s31_req_de")),
        listed("S31.27 AC2: the Germany requester's region: Germany only (a region does not reach up)", "s31_de_token",
               includes=("s31_t_de",), excludes=("s31_t_emea", "s31_t_apac", "s31_t_none"), requesters=("s31_req_de",)),
        listed("S31.28 AC2: the APAC requester's region: APAC only", "s31_apac_token",
               includes=("s31_t_apac",), excludes=("s31_t_emea", "s31_t_de", "s31_t_none"), requesters=("s31_req_apac",)),
        listed("S31.29 AC2: the requester with no unit sees nothing, not even the ticket they raised", "s31_none_token",
               excludes=("s31_t_none",), empty=True,
               desc="A caller with no unit has no region, and a ticket with no unit is in nobody's region."),
        req("S31.30 AC2: the requester with no unit opens their own ticket: the missing-record 404", "GET", inc + "/{{s31_t_none}}", auth="s31_none_token",
            tests=same404),
        req("S31.31 AC5: a policy naming tenant B's org unit is refused: 422", "PUT", acc, auth="admin_a_token",
            headers=key("foreign"), body=placeholder, pre=doc("[N.v('s31_b_unit')]"),
            desc="`in_my_region` lists tenant B's `eng/platform` unit. The answer is the same as for a unit id of no tenant, so it says nothing about tenant B. Nothing is published.",
            tests="""N.problem('invalid_access_policy', 422);
const errs = (N.json().errors || []).map(e => e.pointer + ' ' + e.rule);
test('foreign_id at /rules/policies/1/when/under/of/0', () => expect(errs).to.include('/rules/policies/1/when/under/of/0 foreign_id'));
N.noLeak(N.v('s31_b_unit'));"""),
        req("S31.32 AC5 control: the same policy naming tenant A's EMEA is accepted, then under caller again", "PUT", acc, auth="admin_a_token",
            headers=key("own-unit"), body=placeholder, pre=doc("[N.v('s31_a_unit')]"),
            desc="Only the unit's tenant differs from S31.31. The test script publishes `under caller` back at once.",
            tests="""N.status(200);
test('in_my_region lists EMEA', () => expect(N.json().rules.policies.find(x => x.name === 'in_my_region').when).to.eql({ under: { of: [N.v('s31_a_unit')] } }));
const back = JSON.parse(JSON.stringify(N.json().rules));
back.policies.find(x => x.name === 'in_my_region').when = { under: { of: 'caller' } };
const r = await N.send({ url: N.url('{{core_url}}/api/v1/entity-types/incident/access'), method: 'PUT',
  headers: { Authorization: 'Bearer ' + bru.getVar('admin_a_token'), 'Content-Type': 'application/json', 'If-Match': N.header('ETag'),
    'Idempotency-Key': 'tick953-s31-' + bru.getVar('s31_run') + '-caller-again' },
  data: { rules: back, masks: [] } });
test('under caller republished: 200', () => expect(r.status).to.eql(200));
test('in_my_region is under caller again', () => expect(r.data.rules.policies.find(x => x.name === 'in_my_region').when).to.eql({ under: { of: 'caller' } }));"""),
        req("S31.33 Isolation: Bob lists tenant B's incidents: none of tenant A's", "GET", inc + "?limit=200", auth="bob_token",
            tests="N.status(200);\n" + ids + "".join(hasnt(v) for v in ("s31_t_emea", "s31_t_de", "s31_t_apac", "s31_t_none"))
            + "N.noLeak(N.v('s31_a_unit'), bru.getVar('s31_run'));"),
        req("S31.34 Isolation: Bob opens tenant A's EMEA ticket by id: the missing-record 404", "GET", inc + "/{{s31_t_emea}}", auth="bob_token",
            tests=same404),
        kc_admin("S31.35 Directory: look up EMEA/Germany, EMEA, APAC and the APAC requester in Keycloak", "GET",
                 "/users?exact=true&username={{requester_apac_username}}",
                 desc="Keeps the Keycloak ids S31.36 to S31.38 change. The groups are looked up by path in the test script.",
                 tests="""test('HTTP 200, one user', () => { expect(res.getStatus()).to.eql(200); expect(N.json()).to.have.length(1); });
bru.setVar('s31_kc_apac_user', N.json()[0].id);
for (const [v, p] of [['s31_kc_de', 'ou/EMEA/Germany'], ['s31_kc_emea', 'ou/EMEA'], ['s31_kc_apac', 'ou/APAC']]) {
  const g = await N.send({ url: N.url('{{keycloak_url}}/admin/realms/{{realm}}/group-by-path/t/""" + A + """/' + p),
    method: 'GET', headers: { Authorization: 'Bearer ' + bru.getVar('kc_admin_token') } });
  test(p + ' found', () => expect(g.status).to.eql(200));
  bru.setVar(v, g.data.id);
}"""),
        kc_admin("S31.36 AC3: the directory admin deletes EMEA/Germany", "DELETE", "/groups/{{s31_kc_de}}",
                 desc="Keycloak console: Groups › t › tenant A › ou › EMEA › Germany › Delete. The next group sync tombstones the unit.",
                 tests="test('HTTP 204', () => expect(res.getStatus()).to.eql(204));"),
        kc_admin("S31.37 AC4: the APAC requester leaves APAC", "DELETE", "/users/{{s31_kc_apac_user}}/groups/{{s31_kc_apac}}",
                 desc="Keycloak console: Users › requester-apac › Groups › APAC › Leave.",
                 tests="test('HTTP 204', () => expect(res.getStatus()).to.eql(204));"),
        kc_admin("S31.38 AC4: the APAC requester joins EMEA", "PUT", "/users/{{s31_kc_apac_user}}/groups/{{s31_kc_emea}}",
                 desc="Keycloak console: Users › requester-apac › Groups › Join group › EMEA. Now run one group sync (`run.sh` does), then the folder `S31 region after sync`.",
                 tests="test('HTTP 204', () => expect(res.getStatus()).to.eql(204));\nbru.setVar('change_at', String(Date.now()));\nbru.setVar('poll_n', 0);"),
    ]
    return {
        "dir": "S31", "name": "S31 region",
        "desc": "Story S31, TICK-946 (kit TICK-953, PLAN-011 P11-20, ADR-010 D7, D8, ADR-010-A2). Part one of two. An access policy `in_my_region` (`{\"under\": {\"of\": \"caller\"}}`) grants read on incidents whose org unit is at or below one of the caller's units. AC1 S31.21 to S31.24, AC2 S31.25 to S31.30, AC5 S31.31 and S31.32 (the unit ids come from `run.sh`, see S31.14), isolation S31.33 and S31.34, then the directory changes of AC3 (S31.36) and AC4 (S31.37, S31.38). Run one group sync, then the folder `S31 region after sync`; `docs/acceptance/S31/run.sh` does all of it. Needs `tools/seed.sh` on a stack whose realm has the S31 directory (tenant A: `/ou/EMEA`, `/ou/EMEA/Germany`, `/ou/APAC`, agent-emea and four requesters). One pass per fresh stack: S31.36 deletes EMEA/Germany. Kit: `docs/acceptance/S31/`.",
        "items": items,
    }


def s31_after():
    """Story S31 part two (TICK-953): after the group sync that applied
    S31.36 to S31.38. S31B.9 waits for that sync (it repeats until agent-emea's
    list has no Germany ticket, at most 11 minutes, like S5), so the whole
    collection also runs in one pass. It finds part one's tickets by
    requester, so it needs no runtime variable from S31."""
    inc, ref404, same404, ids, exact_total = _s31_common("S31B.10")
    key = lambda k: {"Idempotency-Key": "tick953-s31b-{{s31b_run}}-" + k}
    by = lambda var: inc + "?limit=200&filter[requester]={{%s}}" % var
    keep = lambda var: """N.status(200);
const items = N.json().items;
test('at least one ticket', () => expect(items.length).to.be.above(0));
bru.setVar('%s', JSON.stringify(items.map(i => i.id)));""" % var
    none_of = lambda var: "test('none of the %s tickets', () => JSON.parse(bru.getVar('%s')).forEach(x => expect(ids).to.not.include(x)));\n" % (var, var)
    wait = "S31B.9 AC3: once the group sync has run, agent-emea's list has no Germany ticket"
    me = lambda name, tok, var: req(name, "GET", "{{core_url}}/api/v1/me", auth=tok,
                                    tests=f"N.me('{A}');\nbru.setVar('{var}', N.json().user_id);")
    items = [
        token("S31B.1 Sign in as admin@tenant-a", "admin_a_username", "admin_a_password", "admin_a_token",
              extra="bru.setVar('s31b_run', Math.random().toString(16).slice(2, 10));"),
        token("S31B.2 Sign in as agent-emea@tenant-a", "agent_emea_username", "agent_emea_password", "s31_agent_token"),
        token("S31B.3 Sign in as the Germany requester", "requester_germany_username", "requester_germany_password", "s31_de_token"),
        token("S31B.4 Sign in as the APAC requester (moved to EMEA)", "requester_apac_username", "requester_apac_password", "s31_apac_token"),
        me("S31B.5 The Germany requester's principal id", "s31_de_token", "s31_req_de"),
        me("S31B.6 The APAC requester's principal id", "s31_apac_token", "s31_req_apac"),
        req("S31B.7 The admin finds the Germany requester's tickets", "GET", by("s31_req_de"), auth="admin_a_token",
            desc="The admin reads every incident (`admins`), so this is every ticket part one raised for them.", tests=keep("s31_de_ids")),
        req("S31B.8 The admin finds the APAC requester's tickets (raised while in APAC)", "GET", by("s31_req_apac"), auth="admin_a_token",
            tests=keep("s31_apac_ids")),
        req(wait, "GET", inc + "?limit=200", auth="s31_agent_token", pre=POLL_PRE,
            desc="The Germany tickets keep their unit, EMEA/Germany, which the sync tombstoned: it has no closure row, so it is outside every region. The EMEA tickets stay. Repeats until the sync has run (at most 11 minutes, like S5); `run.sh` runs one before this folder, so it passes at once.",
            tests=poll(wait, "N.json().items.every(i => !JSON.parse(bru.getVar('s31_de_ids')).includes(i.id))",
                       "N.status(200);\n" + ids + none_of("s31_de_ids") + none_of("s31_apac_ids") + exact_total + """test('still lists at least one EMEA ticket', () => expect(N.json().items.length).to.be.above(0));
console.log('S31B.9 total', N.json().total);""")),
        ref404,
        req("S31B.11 AC3: agent-emea opens a Germany ticket by id: the missing-record 404", "GET",
            inc + "/{{s31_de_first}}", auth="s31_agent_token",
            pre="bru.setVar('s31_de_first', JSON.parse(bru.getVar('s31_de_ids'))[0]);", tests=same404),
        req("S31B.12 AC3: the Germany requester sees nothing now (no unit, no region)", "GET", inc + "?limit=200", auth="s31_de_token",
            tests="N.status(200);\ntest('total 0', () => { expect(N.json().items).to.eql([]); expect(N.json().total).to.eql(0); });"),
        req("S31B.13 AC4: agent-emea opens the APAC requester's old ticket: still the missing-record 404", "GET",
            inc + "/{{s31_apac_first}}", auth="s31_agent_token",
            pre="bru.setVar('s31_apac_first', JSON.parse(bru.getVar('s31_apac_ids'))[0]);",
            desc="The ticket kept the unit it was raised in (APAC). Moving the requester does not move it.", tests=same404),
        req("S31B.14 AC4: the admin creates a new ticket raised by the moved requester", "POST", inc, auth="admin_a_token",
            headers=key("moved"), body={"data": {"short_description": "S31 {{s31b_run}} raised after the move to EMEA", "requester": "{{s31_req_apac}}"}},
            tests="N.status(201);\nbru.setVar('s31_t_moved', N.json().id);"),
        req("S31B.15 AC4: agent-emea lists the new ticket, not the old one", "GET", inc + "?limit=200", auth="s31_agent_token",
            desc="A new ticket takes the requester's unit at creation (now EMEA); the old one stays in APAC.",
            tests="N.status(200);\n" + ids + "test('includes the new ticket', () => expect(ids).to.include(bru.getVar('s31_t_moved')));\n"
            + none_of("s31_apac_ids") + exact_total),
        req("S31B.16 AC4: the moved requester's region: the new ticket, not their old APAC one", "GET", inc + "?limit=200", auth="s31_apac_token",
            desc="Now in EMEA, they see EMEA's tickets. Their old ticket is in APAC, outside their region.",
            tests="N.status(200);\n" + ids + "test('includes the new ticket', () => expect(ids).to.include(bru.getVar('s31_t_moved')));\n"
            + none_of("s31_apac_ids") + exact_total),
    ]
    return {
        "dir": "S31-after", "name": "S31 region after sync",
        "desc": "Story S31, TICK-946 (kit TICK-953). Part two of two: after the group sync that applied part one's directory changes (`S31 region` S31.36 to S31.38). AC3 S31B.9 to S31B.12: EMEA/Germany is gone from the directory, and its tickets drop out of agent-emea's list. AC4 S31B.13 to S31B.16: the requester moved from APAC to EMEA keeps their old ticket in APAC. S31B.9 waits for the sync (at most 11 minutes, like S5); `docs/acceptance/S31/run.sh` runs one first. Kit: `docs/acceptance/S31/`.",
        "items": items,
    }


